"""Strict MILP-master Lagrangian/Benders algorithm for Regime-II MLND.

The implementation intentionally differs from ``benders_experimental.py``:

* the master contains only first-stage design variables ``x/y/z/Gamma`` and
  the recourse estimator ``eta``;
* every ``psi`` variable, every queue variable, and every conic constraint is
  kept in a continuous subproblem;
* no monolithic MISOCP solve is used to obtain an incumbent;
* initial designs are generated by a Lagrangian relaxation of an OD-service
  surrogate;
* two distinct flow-based cut families are generated at integer master
  designs:

  1. aggregate-topology connectivity cuts;
  2. direct/swap-route reachability cuts.

The exact continuous SOCP and its conic-dual Benders cuts are inherited from
``BendersRegimeIISolver``.  The two profit-estimation LPs are relaxations of
that SOCP, so their dual cuts are globally valid upper estimators of recourse.
"""

from __future__ import annotations

import math
import time
from dataclasses import dataclass, field
from typing import Dict, Iterable, List, Mapping, Optional, Sequence, Tuple

import gurobipy as gp
import networkx as nx
from gurobipy import GRB

from src import config
from src.data_processor.instance import Instance
from src.model.Benders import BendersRegimeIISolver, SubproblemResult


Node = str
Arc = Tuple[Node, Node]
Pair = Tuple[Node, Node]


@dataclass
class LagrangianRecord:
    iteration: int
    dual_bound: float
    best_dual_bound: float
    selected_pairs: int
    open_hubs: int
    violation_norm: float
    step_size: float


@dataclass
class LagrangianWarmStartResult:
    designs: List[Dict[str, object]]
    best_dual_bound: float
    history: List[Dict[str, float]]
    wall_time: float
    tabu_history: List[Dict[str, object]] = field(default_factory=list)


@dataclass
class FlowCutStats:
    topology_cuts: int = 0
    swap_reachability_cuts: int = 0
    topology_estimator_cuts: int = 0
    swap_estimator_cuts: int = 0
    topology_max_service_cuts: int = 0
    swap_max_service_cuts: int = 0
    network_net_profit_cuts: int = 0
    screened_iterations: int = 0


class StrictLagrangianBendersSolver(BendersRegimeIISolver):
    """Pure-MILP-master Benders solver with LR starts and flow screening."""

    def __init__(
        self,
        instance: Instance,
        *,
        use_topology_cuts: bool = True,
        use_swap_reachability_cuts: bool = True,
        use_topology_estimator: bool = True,
        use_swap_estimator: bool = True,
        use_lagrangian_warmstart: bool = True,
        use_restricted_network_milp: bool = True,
        use_global_network_upper_bound: bool = True,
        disable_swapping_stations: bool = False,
        relax_gamma_integrality: bool = False,
        lr_iterations: int = 50,
        lr_initial_step: float = 20.0,
        lr_max_designs: int = 8,
        estimator_screen_tolerance: float = 1e-5,
        max_consecutive_estimator_screens: int = 5,
        max_combinatorial_cuts_per_iteration: int = 30,
        pool_solutions: int = 20,
        pool_exact_evaluations_per_iteration: int = 2,
        verbose: bool = True,
    ):
        super().__init__(instance, use_pareto_cuts=False)
        self.disable_swapping_stations = bool(disable_swapping_stations)
        self.relax_gamma_integrality = bool(relax_gamma_integrality)
        if self.disable_swapping_stations:
            for arc, options in self.route_options.items():
                self.route_options[arc] = [
                    option for option in options if option not in self.E
                ]
        self.use_topology_cuts = bool(use_topology_cuts)
        self.use_swap_reachability_cuts = bool(use_swap_reachability_cuts)
        self.use_topology_estimator = bool(use_topology_estimator)
        self.use_swap_estimator = bool(use_swap_estimator)
        self.use_lagrangian_warmstart = bool(use_lagrangian_warmstart)
        self.use_restricted_network_milp = bool(
            use_restricted_network_milp
        )
        self.use_global_network_upper_bound = bool(
            use_global_network_upper_bound
        )
        self.lr_iterations = max(1, int(lr_iterations))
        self.lr_initial_step = float(lr_initial_step)
        self.lr_max_designs = max(1, int(lr_max_designs))
        self.estimator_screen_tolerance = float(estimator_screen_tolerance)
        self.max_consecutive_estimator_screens = max(
            0, int(max_consecutive_estimator_screens)
        )
        self.max_combinatorial_cuts_per_iteration = max(
            0, int(max_combinatorial_cuts_per_iteration)
        )
        self.pool_solutions = max(1, int(pool_solutions))
        self.pool_exact_evaluations_per_iteration = max(
            0, int(pool_exact_evaluations_per_iteration)
        )
        self.verbose = bool(verbose)
        self.flow_cut_stats = FlowCutStats()
        self.lagrangian_result: Optional[LagrangianWarmStartResult] = None
        self._topology_cut_signatures: set[Tuple[Pair, Tuple[Arc, ...]]] = set()
        self._swap_cut_signatures: set[Tuple[Pair, Tuple[Arc, ...]]] = set()
        self._global_operating_ub = self._compute_global_operating_ub()
        self._minimum_cycle_times = self._compute_minimum_cycle_times()
        self._lr_generated = False
        self._pool_exact_signatures: set[Tuple[int, ...]] = set()
        self._estimator_snapshots: Dict[str, Dict[str, object]] = {}
        self.lagrangian_tabu_history: List[Dict[str, object]] = []
        self.global_network_bound: Optional[float] = None
        self.global_network_incumbent: Optional[float] = None
        self.global_network_gap: Optional[float] = None
        self.global_network_status: Optional[int] = None
        self.global_network_wall_time: float = 0.0
        self.initial_design_history: List[Dict[str, object]] = []

    # ------------------------------------------------------------------
    # Strict first-stage MILP master
    # ------------------------------------------------------------------

    def _compute_global_operating_ub(self) -> float:
        revenue = float(getattr(config, "ORDER_REVENUE_COEF", 0.0))
        return max(
            0.0,
            revenue
            * sum(
                max(0.0, float(self.inst.h.get((i, j), 0.0)))
                for i, j in self.A_HH
            ),
        )

    def _compute_minimum_cycle_times(self) -> Dict[Pair, float]:
        """Return a design-independent lower bound on time per served OD unit."""
        return_graph = nx.DiGraph()
        return_graph.add_nodes_from(self.HLS)
        for u, v in [*self.A_SS, *self.A_SL]:
            options = self.route_options.get((u, v), [])
            if not options:
                continue
            return_graph.add_edge(
                u,
                v,
                weight=min(float(self.t[u, v, k]) for k in options),
            )
        return_graph.add_edges_from(
            (u, v, {"weight": 0.0}) for u, v in self.A_virtual
        )

        cycle_times: Dict[Pair, float] = {}
        for i, j in self.A_HH:
            loaded_options = self.route_options.get((i, j), [])
            if not loaded_options:
                continue
            cycle_time = min(
                float(self.t[i, j, k]) for k in loaded_options
            )
            p_i = self._p_chain(i)
            if p_i > 1e-9:
                try:
                    cycle_time += p_i * float(
                        nx.shortest_path_length(
                            return_graph,
                            j,
                            self._hub_pool(i),
                            weight="weight",
                        )
                    )
                except (nx.NetworkXNoPath, nx.NodeNotFound):
                    continue
            if 1.0 - p_i > 1e-9:
                base_times = []
                for l, h in self.A_LH:
                    if h != i:
                        continue
                    try:
                        base_times.append(
                            float(
                                nx.shortest_path_length(
                                    return_graph, j, l, weight="weight"
                                )
                            )
                            + min(
                                [
                                    float(self.t[l, i, k])
                                    for k in self.route_options.get((l, i), [])
                                ]
                                or [math.inf]
                            )
                        )
                    except (nx.NetworkXNoPath, nx.NodeNotFound):
                        continue
                if not base_times:
                    continue
                cycle_time += (1.0 - p_i) * min(base_times)
            if math.isfinite(cycle_time) and cycle_time > 1e-9:
                cycle_times[i, j] = cycle_time
        return cycle_times

    def _add_static_net_profit_bounds(
        self,
        m: gp.Model,
        *,
        x,
        z,
        gamma,
        eta,
        service_possible,
    ) -> None:
        """Add pure-MILP dual bounds on operating profit minus fleet cost."""
        revenue = float(getattr(config, "ORDER_REVENUE_COEF", 0.0))
        flight_rate = float(getattr(config, "COST_FLIGHT_TIME", 0.0))
        drone_cost = float(getattr(config, "COST_DRONE", 0.0))
        tau_h = float(config.TAU_H)
        mu_c = list(config.MU_HUB)

        unit_net = {
            pair: revenue
            - (flight_rate + drone_cost)
            * self._minimum_cycle_times[pair]
            for pair in self._minimum_cycle_times
        }
        if not unit_net:
            return

        m.addConstr(
            eta - drone_cost * gamma
            <= gp.quicksum(
                float(self.inst.h.get(pair, 0.0))
                * max(0.0, unit_net.get(pair, 0.0))
                * service_possible[pair]
                for pair in self.A_HH
            ),
            name="net_profit_cycle_knapsack_ub",
        )

        # For each reference hub-capacity level, choose a valid destination
        # multiplier vector.  Every resulting inequality is a Lagrangian-dual
        # upper bound and remains valid for all actual z decisions.
        reference_capacities = [
            max(0.0, float(mu) - 1.0 / tau_h) for mu in mu_c
        ]
        for ref_index, reference_capacity in enumerate(
            reference_capacities
        ):
            multipliers: Dict[Node, float] = {}
            for destination in self.H:
                pairs = [
                    (i, j)
                    for i, j in self.A_HH
                    if j == destination and (i, j) in unit_net
                ]
                candidates = {0.0}
                candidates.update(
                    max(0.0, unit_net[pair]) for pair in pairs
                )
                multipliers[destination] = min(
                    candidates,
                    key=lambda nu: (
                        nu * reference_capacity
                        + sum(
                            float(self.inst.h.get(pair, 0.0))
                            * max(0.0, unit_net[pair] - nu)
                            for pair in pairs
                        )
                    ),
                )

            capacity_term = gp.quicksum(
                multipliers[j]
                * (
                    gp.quicksum(
                        float(mu_c[c]) * z[j, c]
                        for c in range(len(mu_c))
                    )
                    - x[j] / tau_h
                )
                for j in self.H
            )
            residual_term = gp.quicksum(
                float(self.inst.h.get((i, j), 0.0))
                * max(
                    0.0,
                    unit_net.get((i, j), 0.0) - multipliers[j],
                )
                * service_possible[i, j]
                for i, j in self.A_HH
            )
            m.addConstr(
                eta - drone_cost * gamma
                <= capacity_term + residual_term,
                name=f"net_profit_hub_dual_ub_{ref_index}",
            )

    def build_master(self) -> None:
        if self.master is not None:
            return

        m = gp.Model("MLND_RegimeII_Strict_Lagrangian_Benders_Master")
        m.Params.OutputFlag = int(getattr(config, "BENDERS_MASTER_LOG", 0))
        m.Params.Threads = int(getattr(config, "BENDERS_MASTER_THREADS", 1))
        m.Params.Seed = int(getattr(config, "BENDERS_RANDOM_SEED", 0))
        m.Params.PoolSolutions = self.pool_solutions
        m.Params.PoolSearchMode = int(
            getattr(config, "BENDERS_STRICT_POOL_SEARCH_MODE", 1)
        )

        C = range(len(config.MU_HUB))
        mu_c = list(config.MU_HUB)
        tau_h = float(config.TAU_H)

        x = m.addVars(self.N_x, vtype=GRB.BINARY, name="x")
        y = m.addVars(self.AY, vtype=GRB.BINARY, name="y")
        z = m.addVars(self.H, C, vtype=GRB.BINARY, name="z")
        gamma = m.addVar(
            lb=0.0,
            vtype=(
                GRB.CONTINUOUS
                if self.relax_gamma_integrality
                else GRB.INTEGER
            ),
            name="Gamma",
        )
        service_possible = m.addVars(
            self.A_HH, vtype=GRB.BINARY, name="service_possible"
        )
        route_ready_keys = [
            (i, j, k)
            for i, j in self.A_HH
            for k in self.route_options.get((i, j), [])
            if k in self.E
        ]
        route_ready = m.addVars(
            route_ready_keys, vtype=GRB.BINARY, name="route_ready"
        )
        eta = m.addVar(
            lb=-GRB.INFINITY,
            ub=self._global_operating_ub,
            name="eta",
        )
        if self.disable_swapping_stations:
            for swap in self.E:
                m.addConstr(x[swap] == 0.0, name=f"disable_swap_{swap}")
            for u, v in self.AY:
                if u in self.E or v in self.E:
                    m.addConstr(
                        y[u, v] == 0.0,
                        name=f"disable_swap_arc_{u}_{v}",
                    )

        fixed_cost = gp.quicksum(
            float(self.inst.f.get(l, config.COST_BASE)) * x[l] for l in self.L
        )
        fixed_cost += gp.quicksum(
            float(getattr(config, "COST_HUB_FIXED", 0.0)) * x[i]
            for i in self.H
        )
        fixed_cost += gp.quicksum(
            float(self.inst.f.get(k, config.COST_SWAPPING)) * x[k]
            for k in self.E
        )
        fixed_cost += gp.quicksum(
            float(config.COST_HUB[c]) * z[i, c] for i in self.H for c in C
        )
        fixed_cost += gp.quicksum(
            self.arc_cost[u, v] * y[u, v] for u, v in self.AY
        )
        fixed_cost += float(config.COST_DRONE) * gamma
        m.setObjective(eta - fixed_cost, GRB.MAXIMIZE)

        for i in self.H:
            assigned = [l for l, h in self.A_LH if h == i]
            m.addConstr(
                gp.quicksum(y[l, i] for l in assigned if (l, i) in y) == x[i],
                name=f"assign_{i}",
            )
            m.addConstr(
                gp.quicksum(z[i, c] for c in C) == x[i],
                name=f"capacity_{i}",
            )
            m.addConstr(
                gp.quicksum(float(mu_c[c]) * z[i, c] for c in C)
                >= x[i] / tau_h,
                name=f"hub_min_slack_{i}",
            )

        for l, i in self.A_LH:
            m.addConstr(y[l, i] <= x[l], name=f"assign_active_{l}_{i}")

        for u, v in self.AY:
            if (u, v) in self.A_LH:
                continue
            m.addConstr(
                y[u, v] <= self._node_activation_expr({"x": x}, u),
                name=f"arc_tail_active_{u}_{v}",
            )
            m.addConstr(
                y[u, v] <= self._node_activation_expr({"x": x}, v),
                name=f"arc_head_active_{u}_{v}",
            )

        revenue = float(getattr(config, "ORDER_REVENUE_COEF", 0.0))
        for i, j in self.A_HH:
            m.addConstr(
                service_possible[i, j] <= x[i],
                name=f"service_origin_open_{i}_{j}",
            )
            m.addConstr(
                service_possible[i, j] <= x[j],
                name=f"service_destination_open_{i}_{j}",
            )
            if (i, j) in y:
                m.addConstr(
                    service_possible[i, j] <= y[i, j],
                    name=f"service_loaded_arc_{i}_{j}",
                )
            else:
                m.addConstr(
                    service_possible[i, j] == 0.0,
                    name=f"service_no_loaded_arc_{i}_{j}",
                )
            ready_terms = []
            if "0" in self.route_options.get((i, j), []) and (i, j) in y:
                ready_terms.append(y[i, j])
            for k in self.route_options.get((i, j), []):
                if k not in self.E:
                    continue
                ready = route_ready[i, j, k]
                requirements = ((i, j), (i, k), (k, j))
                for arc in requirements:
                    if arc in y:
                        m.addConstr(
                            ready <= y[arc],
                            name=f"route_ready_ub_{i}_{j}_{k}_{arc[0]}_{arc[1]}",
                        )
                    else:
                        m.addConstr(ready == 0.0)
                if all(arc in y for arc in requirements):
                    m.addConstr(
                        ready
                        >= y[i, j] + y[i, k] + y[k, j] - 2.0,
                        name=f"route_ready_lb_{i}_{j}_{k}",
                    )
                ready_terms.append(ready)
            if ready_terms:
                m.addConstr(
                    service_possible[i, j] <= gp.quicksum(ready_terms),
                    name=f"service_route_available_{i}_{j}",
                )
            else:
                m.addConstr(
                    service_possible[i, j] == 0.0,
                    name=f"service_no_route_{i}_{j}",
                )
            if (i, j) not in self._minimum_cycle_times:
                m.addConstr(
                    service_possible[i, j] == 0.0,
                    name=f"service_no_structural_cycle_{i}_{j}",
                )
        m.addConstr(
            eta
            <= gp.quicksum(
                revenue
                * max(0.0, float(self.inst.h.get((i, j), 0.0)))
                * service_possible[i, j]
                for i, j in self.A_HH
            ),
            name="eta_service_logic_ub",
        )
        if self._minimum_cycle_times:
            max_revenue_per_time = max(
                revenue / cycle_time
                for cycle_time in self._minimum_cycle_times.values()
            )
            m.addConstr(
                eta <= max_revenue_per_time * gamma,
                name="eta_fleet_time_ub",
            )
        m.addConstr(
            eta
            <= revenue
            * gp.quicksum(
                gp.quicksum(float(mu_c[c]) * z[i, c] for c in C)
                - x[i] / tau_h
                for i in self.H
            ),
            name="eta_hub_capacity_ub",
        )
        self._add_static_net_profit_bounds(
            m,
            x=x,
            z=z,
            gamma=gamma,
            eta=eta,
            service_possible=service_possible,
        )

        drone_cost = float(config.COST_DRONE)
        if drone_cost > 1e-9:
            # Close-all has value zero.  Any solution with fleet cost above the
            # global revenue upper bound is dominated, so this preserves at
            # least one globally optimal solution while bounding the master.
            gamma_ub = int(math.ceil(self._global_operating_ub / drone_cost))
            m.addConstr(gamma <= gamma_ub, name="gamma_optimality_ub")

        self.master = m
        self.master_vars = {
            "x": x,
            "y": y,
            "z": z,
            "Gamma": gamma,
            "eta": eta,
            "service_possible": service_possible,
            "od_service_ub": {},
            "route_ready": route_ready,
        }
        m.update()
        forbidden_prefixes = (
            "psi",
            "rho_",
            "alpha",
            "beta",
            "varphi",
            "lambda",
            "xi",
            "q_v",
            "q_t",
            "h_v",
            "h_t",
        )
        forbidden = [
            var.VarName
            for var in m.getVars()
            if var.VarName.startswith(forbidden_prefixes)
        ]
        if forbidden or int(m.NumQConstrs) != 0:
            raise RuntimeError(
                "Strict master invariant violated: operational flow/queue "
                f"variables or conic constraints detected: {forbidden[:5]}"
            )

    # ------------------------------------------------------------------
    # LP maximum-profit estimators
    # ------------------------------------------------------------------

    def _estimator_common(
        self,
        design: Mapping[str, object],
        *,
        label: str,
        swap_aware: bool,
        objective_kind: str = "profit",
        fixed_capacity_queue: bool = False,
        optimize_gamma_net: bool = False,
        optimize_network: bool = False,
        optimize_facilities: bool = False,
        global_bound_only: bool = False,
        hub_add_minimum: Optional[int] = None,
        hub_add_limit: Optional[int] = None,
        hub_drop_limit: Optional[int] = None,
        min_open_hubs: Optional[int] = None,
        max_open_hubs: Optional[int] = None,
        min_open_arcs: Optional[int] = None,
        support_add_limit: Optional[int] = None,
        support_drop_limit: Optional[int] = None,
        max_open_bases: Optional[int] = None,
        max_open_swaps: Optional[int] = None,
        facility_hub_utilization_limit: Optional[float] = None,
        network_time_limit: Optional[float] = None,
    ) -> SubproblemResult:
        """Solve a linear upper-estimation subproblem at a fixed design.

        ``swap_aware=False`` keeps aggregate circulation but ignores explicit
        route availability.  ``swap_aware=True`` adds direct/swap route
        decomposition and physical-arc activation.  Both relax queueing and
        battery-consumption constraints, hence both upper-bound exact recourse.
        """
        kind = "swap" if swap_aware else "topology"
        m = gp.Model(f"MLND_RegimeII_{kind}_ProfitEstimator_{label}")
        m.Params.OutputFlag = int(
            getattr(config, "BENDERS_ESTIMATOR_LOG", 0)
        )
        m.Params.Threads = int(getattr(config, "BENDERS_SUB_THREADS", 1))
        m.Params.Seed = int(getattr(config, "BENDERS_RANDOM_SEED", 0))
        m.Params.DualReductions = 0
        if network_time_limit is not None:
            m.Params.TimeLimit = max(0.01, float(network_time_limit))

        C = range(len(config.MU_HUB))
        mu_c = list(config.MU_HUB)
        tau_h = float(config.TAU_H)
        total_demand = max(
            1.0, sum(float(value) for value in self.inst.h.values())
        )
        rhs_design: Mapping[str, object] = design
        network_y = None
        network_z = None
        network_x = None
        fixed_x = None
        if optimize_network:
            if not swap_aware or not optimize_gamma_net:
                raise ValueError(
                    "Network optimization requires swap-aware Gamma optimization."
                )
            if optimize_facilities:
                network_x = m.addVars(
                    self.N_x, vtype=GRB.BINARY, name="network_x"
                )
                for u in self.N_x:
                    network_x[u].Start = float(
                        float(design["x"].get(u, 0.0)) > 0.5
                    )
                x_reference = network_x
                seed_open_hubs = [
                    h
                    for h in self.H
                    if float(design["x"].get(h, 0.0)) > 0.5
                ]
                seed_closed_hubs = [
                    h for h in self.H if h not in seed_open_hubs
                ]
                support_nodes = [*self.L, *self.E]
                seed_open_support = [
                    u
                    for u in support_nodes
                    if float(design["x"].get(u, 0.0)) > 0.5
                ]
                seed_closed_support = [
                    u for u in support_nodes if u not in seed_open_support
                ]
                if hub_add_limit is not None:
                    m.addConstr(
                        gp.quicksum(
                            network_x[h] for h in seed_closed_hubs
                        )
                        <= max(0, int(hub_add_limit)),
                        name="facility_hub_add_limit",
                    )
                if hub_add_minimum is not None:
                    m.addConstr(
                        gp.quicksum(
                            network_x[h] for h in seed_closed_hubs
                        )
                        >= min(
                            len(seed_closed_hubs),
                            max(0, int(hub_add_minimum)),
                        ),
                        name="facility_hub_add_minimum",
                    )
                if hub_drop_limit is not None:
                    m.addConstr(
                        gp.quicksum(
                            1.0 - network_x[h] for h in seed_open_hubs
                        )
                        <= max(0, int(hub_drop_limit)),
                        name="facility_hub_drop_limit",
                    )
                if min_open_hubs is not None:
                    m.addConstr(
                        gp.quicksum(network_x[h] for h in self.H)
                        >= min(len(self.H), max(0, int(min_open_hubs))),
                        name="facility_min_open_hubs",
                    )
                if max_open_hubs is not None:
                    m.addConstr(
                        gp.quicksum(network_x[h] for h in self.H)
                        <= min(len(self.H), max(0, int(max_open_hubs))),
                        name="facility_max_open_hubs",
                    )
                if support_add_limit is not None:
                    m.addConstr(
                        gp.quicksum(
                            network_x[u] for u in seed_closed_support
                        )
                        <= max(0, int(support_add_limit)),
                        name="facility_support_add_limit",
                    )
                if support_drop_limit is not None:
                    m.addConstr(
                        gp.quicksum(
                            1.0 - network_x[u]
                            for u in seed_open_support
                        )
                        <= max(0, int(support_drop_limit)),
                        name="facility_support_drop_limit",
                    )
                if max_open_bases is not None:
                    m.addConstr(
                        gp.quicksum(network_x[l] for l in self.L)
                        <= max(0, int(max_open_bases)),
                        name="facility_max_open_bases",
                    )
                if max_open_swaps is not None:
                    m.addConstr(
                        gp.quicksum(network_x[k] for k in self.E)
                        <= max(0, int(max_open_swaps)),
                        name="facility_max_open_swaps",
                    )
            else:
                fixed_x = {
                    u: float(float(design["x"].get(u, 0.0)) > 0.5)
                    for u in self.N_x
                }
                x_reference = fixed_x
            network_y = m.addVars(self.AY, vtype=GRB.BINARY, name="network_y")
            network_z = m.addVars(
                self.H, C, vtype=GRB.BINARY, name="network_z"
            )
            if optimize_facilities and min_open_arcs is not None:
                m.addConstr(
                    gp.quicksum(network_y[arc] for arc in self.AY)
                    >= min(len(self.AY), max(0, int(min_open_arcs))),
                    name="facility_min_open_arcs",
                )
            for arc in self.AY:
                network_y[arc].Start = float(
                    float(design["y"].get(arc, 0.0)) > 0.5
                )
            for i in self.H:
                for c in C:
                    network_z[i, c].Start = float(
                        float(design["z"].get((i, c), 0.0)) > 0.5
                    )
            rhs_design = {
                "x": x_reference,
                "y": network_y,
                "z": network_z,
                "Gamma": float(design.get("Gamma", 0.0)),
            }

            for i in self.H:
                assigned = [l for l, h in self.A_LH if h == i]
                m.addConstr(
                    gp.quicksum(network_y[l, i] for l in assigned)
                    == x_reference[i],
                    name=f"network_assign_{i}",
                )
                m.addConstr(
                    gp.quicksum(network_z[i, c] for c in C)
                    == x_reference[i],
                    name=f"network_capacity_{i}",
                )
                m.addConstr(
                    gp.quicksum(
                        float(mu_c[c]) * network_z[i, c] for c in C
                    )
                    >= x_reference[i] / tau_h,
                    name=f"network_hub_min_slack_{i}",
                )
            for l, i in self.A_LH:
                m.addConstr(
                    network_y[l, i] <= x_reference[l],
                    name=f"network_assign_active_{l}_{i}",
                )
            for u, v in self.AY:
                if (u, v) in self.A_LH:
                    continue
                tail = (
                    x_reference[self.inst.s_to_h[u]]
                    if u in self.S
                    else x_reference[u]
                )
                head = (
                    x_reference[self.inst.s_to_h[v]]
                    if v in self.S
                    else x_reference[v]
                )
                m.addConstr(
                    network_y[u, v] <= tail,
                    name=f"network_tail_active_{u}_{v}",
                )
                m.addConstr(
                    network_y[u, v] <= head,
                    name=f"network_head_active_{u}_{v}",
                )

        rho_l = m.addVars(self.L, lb=0.0, name="rho_l")
        rho_s = m.addVars(self.S, lb=0.0, name="rho_s")
        alpha_keys = [
            (l, i, j)
            for l, i in self.A_LH
            for i2, j in self.A_HH
            if i2 == i
        ]
        alpha = m.addVars(alpha_keys, lb=0.0, name="alpha")
        beta = m.addVars(self.A_HH, lb=0.0, name="beta")
        psi = m.addVars(self.A, lb=0.0, name="psi")
        varphi_keys = [
            (u, v, k)
            for u, v in self.A_F
            for k in self.route_options.get((u, v), [])
        ]
        varphi = (
            m.addVars(varphi_keys, lb=0.0, name="varphi")
            if swap_aware
            else None
        )
        gamma_opt = None
        if optimize_gamma_net:
            drone_cost = float(config.COST_DRONE)
            gamma_ub = (
                self._global_operating_ub / drone_cost
                if drone_cost > 1e-9
                else self._global_operating_ub
            )
            gamma_opt = m.addVar(
                lb=0.0,
                ub=max(0.0, float(gamma_ub)),
                name="Gamma_estimator",
            )

        param_constrs: List[Tuple[gp.Constr, object, float]] = []

        def rhs_value(rhs_fun):
            value = rhs_fun(rhs_design)
            if optimize_network:
                return value
            return float(value)

        def add_le(lhs, rhs_fun, name: str):
            value = rhs_value(rhs_fun)
            con = m.addConstr(lhs <= value, name=name)
            if not optimize_network:
                param_constrs.append((con, rhs_fun, value))
            return con

        def add_ge(lhs, rhs_fun, name: str):
            value = rhs_value(rhs_fun)
            con = m.addConstr(lhs >= value, name=name)
            if not optimize_network:
                param_constrs.append((con, rhs_fun, value))
            return con

        for l in self.L:
            add_le(rho_l[l], self._rhs_x(l), f"rho_L_{l}")
        for i, s in self.A_HS:
            add_le(rho_s[s], self._rhs_x(i), f"rho_S_{s}")

        for l, i, j in alpha_keys:
            m.addConstr(alpha[l, i, j] <= rho_l[l])
            add_le(alpha[l, i, j], self._rhs_y(l, i), f"alpha_assign_{l}_{i}_{j}")
            add_le(alpha[l, i, j], self._rhs_y(i, j), f"alpha_arc_{l}_{i}_{j}")
            add_ge(
                alpha[l, i, j] - rho_l[l],
                self._rhs_alpha_lb(l, i, j),
                f"alpha_lb_{l}_{i}_{j}",
            )

        for s, i in self.A_SH:
            for h, j in self.A_HH:
                if h != i:
                    continue
                m.addConstr(beta[i, j] <= rho_s[s])
                add_le(beta[i, j], self._rhs_y(i, j), f"beta_arc_{i}_{j}")
                add_ge(
                    beta[i, j] - rho_s[s],
                    self._rhs_beta_lb(i, j),
                    f"beta_lb_{i}_{j}",
                )

        for i, j in self.A_HH:
            demand = float(self.inst.h.get((i, j), 0.0))
            p_i = self._p_chain(i)
            m.addConstr(
                psi[i, j]
                == demand
                * (
                    (1.0 - p_i)
                    * gp.quicksum(
                        alpha[l, i, j]
                        for l, h in self.A_LH
                        if h == i and (l, i, j) in alpha
                    )
                    + p_i * beta[i, j]
                ),
                name=f"psi_HH_{i}_{j}",
            )

        for l, i in self.A_LH:
            m.addConstr(
                psi[l, i]
                == gp.quicksum(
                    float(self.inst.h.get((i, j), 0.0))
                    * (1.0 - self._p_chain(i))
                    * alpha[l, i, j]
                    for h, j in self.A_HH
                    if h == i and (l, i, j) in alpha
                ),
                name=f"psi_LH_{l}_{i}",
            )

        for s, i in self.A_SH:
            m.addConstr(
                psi[s, i]
                == gp.quicksum(
                    float(self.inst.h.get((i, j), 0.0))
                    * self._p_chain(i)
                    * beta[i, j]
                    for h, j in self.A_HH
                    if h == i
                ),
                name=f"psi_SH_{s}_{i}",
            )

        for u, v in self.A_hat:
            add_le(
                psi[u, v],
                self._rhs_y(u, v, total_demand),
                f"aggregate_arc_active_{u}_{v}",
            )

        for q in self.HLS:
            m.addConstr(
                gp.quicksum(psi[u, q] for u, v in self.A if v == q)
                == gp.quicksum(psi[q, v] for u, v in self.A if u == q),
                name=f"flow_balance_{q}",
            )

        for j in self.H:
            incoming = gp.quicksum(
                psi[u, j] for u, v in self.A if v == j
            )

            def hub_capacity_rhs(d, j=j):
                return sum(
                    float(mu_c[c]) * d["z"][j, c] for c in C
                ) - d["x"][j] / tau_h

            add_le(incoming, hub_capacity_rhs, f"hub_capacity_{j}")
            if (
                optimize_facilities
                and not global_bound_only
                and facility_hub_utilization_limit is not None
            ):
                utilization_limit = min(
                    0.999,
                    max(0.0, float(facility_hub_utilization_limit)),
                )
                m.addConstr(
                    incoming
                    <= utilization_limit
                    * gp.quicksum(
                        float(mu_c[c]) * network_z[j, c] for c in C
                    ),
                    name=f"facility_hub_utilization_{j}",
                )

        # Piecewise-linear tangent underestimators of the convex queue terms.
        # They preserve the estimator as an LP relaxation while materially
        # improving the fleet-time lower bound used to rank LR candidates.
        queue_l = m.addVars(self.L, lb=0.0, name="queue_l_lb")
        queue_s = m.addVars(self.S, lb=0.0, name="queue_s_lb")
        queue_h = m.addVars(self.H, lb=0.0, name="queue_h_lb")
        utilization_points = tuple(
            float(value)
            for value in getattr(
                config,
                "BENDERS_ESTIMATOR_QUEUE_POINTS",
                (0.05, 0.15, 0.30, 0.45, 0.60, 0.72, 0.82, 0.90, 0.95),
            )
            if 0.0 <= float(value) < 1.0
        )
        for q, rho_var, queue_var in [
            *[(l, rho_l[l], queue_l[l]) for l in self.L],
            *[(s, rho_s[s], queue_s[s]) for s in self.S],
        ]:
            for point_index, point in enumerate(utilization_points):
                value = point / (1.0 - point)
                slope = 1.0 / ((1.0 - point) ** 2)
                m.addConstr(
                    queue_var >= value + slope * (rho_var - point),
                    name=f"queue_tangent_{q}_{point_index}",
                )

        mu_max = max(float(value) for value in config.MU_HUB)
        for i in self.H:
            arrival = gp.quicksum(
                psi[u, i] for u, v in self.A if v == i
            )
            queue_mu = mu_max
            if fixed_capacity_queue:
                queue_mu = sum(
                    float(config.MU_HUB[c])
                    * float(design["z"].get((i, c), 0.0))
                    for c in C
                )
                if queue_mu <= 1e-9:
                    m.addConstr(queue_h[i] == 0.0)
                    continue
            for point_index, utilization in enumerate(utilization_points):
                point = utilization * queue_mu
                value = point / (queue_mu - point)
                slope = queue_mu / ((queue_mu - point) ** 2)
                m.addConstr(
                    queue_h[i] >= value + slope * (arrival - point),
                    name=f"queue_h_tangent_{i}_{point_index}",
                )

        queue_time_lb = (
            gp.quicksum(queue_l[l] for l in self.L)
            + gp.quicksum(queue_s[s] for s in self.S)
            + gp.quicksum(queue_h[i] for i in self.H)
        )

        if swap_aware:
            assert varphi is not None
            for u, v in self.A_hat:
                m.addConstr(
                    gp.quicksum(
                        varphi[u, v, k]
                        for k in self.route_options.get((u, v), [])
                        if (u, v, k) in varphi
                    )
                    == psi[u, v],
                    name=f"route_{u}_{v}",
                )
            for u, v, k in varphi_keys:
                big_m = self.route_big_m[u, v, k]
                add_le(
                    varphi[u, v, k],
                    self._rhs_y(u, v, big_m),
                    f"route_arc_{u}_{v}_{k}",
                )
                if k in self.E:
                    add_le(
                        varphi[u, v, k],
                        self._rhs_y(u, k, big_m),
                        f"route_swap_in_{u}_{v}_{k}",
                    )
                    add_le(
                        varphi[u, v, k],
                        self._rhs_y(k, v, big_m),
                        f"route_swap_out_{u}_{v}_{k}",
                    )
            omega = float(config.ENERGY_RATE_OMEGA)
            usable_battery = (
                1.0
                - float(
                    getattr(
                        config,
                        "ENERGY_EPSILON",
                        getattr(config, "EPS", 0.0),
                    )
                )
            ) * float(config.BATTERY_CAPACITY_OMEGA_UPPER)
            for l in self.L:
                m.addConstr(
                    omega
                    * gp.quicksum(
                        self.t[l, i, k] * varphi[l, i, k]
                        for u, i, k in varphi_keys
                        if u == l and (l, i) in self.A_LH
                    )
                    <= usable_battery
                    * gp.quicksum(
                        varphi[l, i, k]
                        for u, i, k in varphi_keys
                        if u == l and (l, i) in self.A_LH and k in self.E
                    ),
                    name=f"energy_relax_L_{l}",
                )
            for i, s in self.A_HS:
                m.addConstr(
                    omega
                    * (
                        queue_h[i]
                        + queue_s[s]
                        + gp.quicksum(
                            self.t[i, j, k] * varphi[i, j, k]
                            for h, j, k in varphi_keys
                            if h == i and (i, j) in self.A_HH
                        )
                        + gp.quicksum(
                            self.t[s, v, k] * varphi[s, v, k]
                            for u, v, k in varphi_keys
                            if u == s
                            and (
                                (s, v) in self.A_SL
                                or (s, v) in self.A_SS
                            )
                        )
                    )
                    <= usable_battery
                    * (
                        gp.quicksum(
                            varphi[i, j, k]
                            for h, j, k in varphi_keys
                            if h == i
                            and (i, j) in self.A_HH
                            and k in self.E
                        )
                        + gp.quicksum(
                            varphi[s, v, k]
                            for u, v, k in varphi_keys
                            if u == s
                            and (
                                (s, v) in self.A_SL
                                or (s, v) in self.A_SS
                            )
                            and k in self.E
                        )
                    ),
                    name=f"energy_relax_HS_{i}",
                )
            total_time = queue_time_lb + gp.quicksum(
                self.t[u, v, k] * varphi[u, v, k]
                for u, v, k in varphi_keys
            )
            operating_cost = gp.quicksum(
                self.flight_cost[u, v, k] * varphi[u, v, k]
                for u, v, k in varphi_keys
            )
        else:
            min_time = {
                (u, v): min(
                    [float(self.t[u, v, k]) for k in self.route_options.get((u, v), [])]
                    or [0.0]
                )
                for u, v in self.A_hat
            }
            min_cost = {
                (u, v): min(
                    [
                        float(self.flight_cost[u, v, k])
                        for k in self.route_options.get((u, v), [])
                    ]
                    or [0.0]
                )
                for u, v in self.A_hat
            }
            total_time = queue_time_lb + gp.quicksum(
                min_time[u, v] * psi[u, v] for u, v in self.A_hat
            )
            operating_cost = gp.quicksum(
                min_cost[u, v] * psi[u, v] for u, v in self.A_hat
            )

        if gamma_opt is None:
            add_le(total_time, self._rhs_gamma(), "fleet_time_relaxation")
        else:
            m.addConstr(
                total_time <= gamma_opt,
                name="fleet_time_relaxation_optimized",
            )

        revenue = float(getattr(config, "ORDER_REVENUE_COEF", 0.0))
        served_benefit = gp.quicksum(
            revenue * psi[i, j] for i, j in self.A_HH
        )
        if objective_kind == "service":
            m.setObjective(
                gp.quicksum(psi[i, j] for i, j in self.A_HH),
                GRB.MAXIMIZE,
            )
        elif objective_kind == "profit":
            objective = served_benefit - operating_cost
            if gamma_opt is not None:
                objective -= float(config.COST_DRONE) * gamma_opt
            if optimize_network:
                assert network_y is not None
                assert network_z is not None
                x_cost = network_x if optimize_facilities else fixed_x
                assert x_cost is not None
                objective -= sum(
                    float(self.inst.f.get(l, config.COST_BASE)) * x_cost[l]
                    for l in self.L
                )
                objective -= sum(
                    float(self.inst.f.get(k, config.COST_SWAPPING))
                    * x_cost[k]
                    for k in self.E
                )
                objective -= sum(
                    float(getattr(config, "COST_HUB_FIXED", 0.0))
                    * x_cost[i]
                    for i in self.H
                )
                objective -= gp.quicksum(
                    float(config.COST_HUB[c]) * network_z[i, c]
                    for i in self.H
                    for c in C
                )
                objective -= gp.quicksum(
                    self.arc_cost[arc] * network_y[arc]
                    for arc in self.AY
                )
            m.setObjective(objective, GRB.MAXIMIZE)
        else:
            raise ValueError(f"Unknown estimator objective: {objective_kind}")
        m.optimize()

        if optimize_facilities and global_bound_only:
            bound = float(m.ObjBound)
            if (
                m.Status
                not in {GRB.OPTIMAL, GRB.TIME_LIMIT, GRB.SUBOPTIMAL}
                or not math.isfinite(bound)
            ):
                return SubproblemResult(
                    status=int(m.Status),
                    obj_value=None,
                    cut_expr_data=None,
                    rhs_at_reference=None,
                    design=design,
                    label=label,
                )
            self._estimator_snapshots[label] = {
                "global_milp_bound": bound,
                "global_milp_incumbent": (
                    None if m.SolCount == 0 else float(m.ObjVal)
                ),
                "global_milp_gap": (
                    None if m.SolCount == 0 else float(m.MIPGap)
                ),
            }
            return SubproblemResult(
                status=int(m.Status),
                obj_value=bound,
                cut_expr_data=None,
                rhs_at_reference=None,
                design=design,
                label=label,
            )

        valid_statuses = (
            {GRB.OPTIMAL, GRB.TIME_LIMIT, GRB.SUBOPTIMAL}
            if optimize_network
            else {GRB.OPTIMAL}
        )
        if m.Status not in valid_statuses or m.SolCount == 0:
            return SubproblemResult(
                status=int(m.Status),
                obj_value=None,
                cut_expr_data=None,
                rhs_at_reference=None,
                design=design,
                label=label,
            )

        self._estimator_snapshots[label] = {
            "swap_aware": bool(swap_aware),
            "objective_kind": objective_kind,
            "psi": {
                (u, v): float(psi[u, v].X)
                for u, v in self.A
            },
            "varphi": (
                {
                    (u, v, k): float(varphi[u, v, k].X)
                    for u, v, k in varphi_keys
                }
                if varphi is not None
                else {}
            ),
            "rho_l": {l: float(rho_l[l].X) for l in self.L},
            "rho_s": {s: float(rho_s[s].X) for s in self.S},
            "total_time_lb": float(total_time.getValue()),
            "operating_cost_lb": float(operating_cost.getValue()),
            "gamma_opt": (
                None if gamma_opt is None else float(gamma_opt.X)
            ),
            "optimized_design": (
                {
                    "x": (
                        {
                            u: float(network_x[u].X > 0.5)
                            for u in self.N_x
                        }
                        if optimize_facilities
                        else dict(fixed_x)
                    ),
                    "y": {
                        arc: float(network_y[arc].X > 0.5)
                        for arc in self.AY
                    },
                    "z": {
                        (i, c): float(network_z[i, c].X > 0.5)
                        for i in self.H
                        for c in C
                    },
                    "Gamma": float(max(0, round(gamma_opt.X))),
                }
                if optimize_network
                else None
            ),
        }

        if optimize_network:
            return SubproblemResult(
                status=int(m.Status),
                obj_value=float(m.ObjVal),
                cut_expr_data=None,
                rhs_at_reference=None,
                design=design,
                label=label,
            )

        dual_tol = float(getattr(config, "BENDERS_DUAL_TOL", 1e-8))
        cut_data = []
        rhs_values = []
        for con, rhs_fun, rhs_ref in param_constrs:
            pi = float(con.Pi)
            if abs(pi) <= dual_tol:
                continue
            cut_data.append((pi, rhs_fun))
            rhs_values.append(rhs_ref)
        return SubproblemResult(
            status=int(m.Status),
            obj_value=float(m.ObjVal),
            cut_expr_data=cut_data,
            rhs_at_reference=rhs_values,
            design=design,
            label=label,
        )

    def solve_topology_profit_estimator(
        self, design: Mapping[str, object], label: str
    ) -> SubproblemResult:
        return self._estimator_common(
            design, label=label, swap_aware=False, objective_kind="profit"
        )

    def solve_swap_profit_estimator(
        self, design: Mapping[str, object], label: str
    ) -> SubproblemResult:
        return self._estimator_common(
            design, label=label, swap_aware=True, objective_kind="profit"
        )

    def solve_swap_ranking_estimator(
        self, design: Mapping[str, object], label: str
    ) -> SubproblemResult:
        """Tighter fixed-design LP used only for heuristic ranking.

        Capacity-specific queue tangents depend on the fixed design.  The
        resulting value is a valid upper bound for that design, but its dual is
        intentionally never installed as a global Benders cut.
        """
        return self._estimator_common(
            design,
            label=label,
            swap_aware=True,
            objective_kind="profit",
            fixed_capacity_queue=True,
        )

    def solve_swap_network_net_estimator(
        self, design: Mapping[str, object], label: str
    ) -> SubproblemResult:
        """Upper-bound net recourse over every fleet size for one network."""
        return self._estimator_common(
            design,
            label=label,
            swap_aware=True,
            objective_kind="profit",
            fixed_capacity_queue=True,
            optimize_gamma_net=True,
        )

    def solve_restricted_network_milp(
        self,
        design: Mapping[str, object],
        label: str,
        *,
        time_limit: float,
    ) -> SubproblemResult:
        """Jointly optimize arcs, capacities and fleet for fixed facilities.

        This is a primal-recovery neighborhood MILP built from the linear
        swap-aware estimator.  It contains no conic constraints and its dual
        information is never used as a global Benders cut.
        """
        return self._estimator_common(
            design,
            label=label,
            swap_aware=True,
            objective_kind="profit",
            fixed_capacity_queue=False,
            optimize_gamma_net=True,
            optimize_network=True,
            network_time_limit=time_limit,
        )

    def solve_global_network_upper_bound(
        self,
        seed_design: Mapping[str, object],
        label: str,
        *,
        time_limit: float,
    ) -> SubproblemResult:
        """Solve a global MILP relaxation and return its rigorous objective bound.

        Facility, arc and capacity decisions remain binary, while Gamma and all
        operational variables are continuous and the queueing cones are
        replaced by tangent lower bounds.  The model is therefore a relaxation
        of the original MISOCP.  Only ``ObjBound`` is returned; its incumbent is
        never accepted as a feasible solution of the strict algorithm.
        """
        return self._estimator_common(
            seed_design,
            label=label,
            swap_aware=True,
            objective_kind="profit",
            fixed_capacity_queue=False,
            optimize_gamma_net=True,
            optimize_network=True,
            optimize_facilities=True,
            global_bound_only=True,
            network_time_limit=time_limit,
        )

    def solve_lr_facility_neighborhood_milp(
        self,
        seed_design: Mapping[str, object],
        label: str,
        *,
        time_limit: float,
        hub_add_minimum: int,
        hub_add_limit: int,
        hub_drop_limit: int,
        min_open_hubs: int,
        max_open_hubs: int,
        min_open_arcs: int,
        support_add_limit: int,
        support_drop_limit: int,
        max_open_bases: int,
        max_open_swaps: int,
        hub_utilization_limit: float,
    ) -> SubproblemResult:
        """Optimize an LR-centered facility/network Hamming neighborhood."""
        return self._estimator_common(
            seed_design,
            label=label,
            swap_aware=True,
            objective_kind="profit",
            fixed_capacity_queue=False,
            optimize_gamma_net=True,
            optimize_network=True,
            optimize_facilities=True,
            hub_add_minimum=hub_add_minimum,
            hub_add_limit=hub_add_limit,
            hub_drop_limit=hub_drop_limit,
            min_open_hubs=min_open_hubs,
            max_open_hubs=max_open_hubs,
            min_open_arcs=min_open_arcs,
            support_add_limit=support_add_limit,
            support_drop_limit=support_drop_limit,
            max_open_bases=max_open_bases,
            max_open_swaps=max_open_swaps,
            facility_hub_utilization_limit=hub_utilization_limit,
            network_time_limit=time_limit,
        )

    def solve_topology_max_service_estimator(
        self, design: Mapping[str, object], label: str
    ) -> SubproblemResult:
        return self._estimator_common(
            design, label=label, swap_aware=False, objective_kind="service"
        )

    def solve_swap_max_service_estimator(
        self, design: Mapping[str, object], label: str
    ) -> SubproblemResult:
        return self._estimator_common(
            design, label=label, swap_aware=True, objective_kind="service"
        )

    def _service_result_as_profit_cut(
        self, result: SubproblemResult
    ) -> SubproblemResult:
        revenue = float(getattr(config, "ORDER_REVENUE_COEF", 0.0))
        return SubproblemResult(
            status=result.status,
            obj_value=(
                None
                if result.obj_value is None
                else revenue * float(result.obj_value)
            ),
            cut_expr_data=(
                None
                if result.cut_expr_data is None
                else [
                    (revenue * float(pi), rhs_fun)
                    for pi, rhs_fun in result.cut_expr_data
                ]
            ),
            rhs_at_reference=result.rhs_at_reference,
            design=result.design,
            label=f"{result.label}_profit_scaled",
        )

    def add_network_net_profit_cut(
        self,
        design: Mapping[str, object],
        net_upper_bound: float,
        *,
        prefix: str = "network_net_profit",
    ) -> None:
        """Condition a net-profit upper bound on one binary network.

        If the master binary variables match ``design``, the Hamming-distance
        expression is zero and the cut enforces the optimized LP net bound for
        every Gamma.  If at least one binary changes, the big-M coefficient
        raises the RHS to the global operating-revenue upper bound, making the
        inequality redundant and therefore globally valid.
        """
        assert self.master is not None
        x = self.master_vars["x"]
        y = self.master_vars["y"]
        z = self.master_vars["z"]
        gamma = self.master_vars["Gamma"]
        eta = self.master_vars["eta"]
        mismatch_terms = []
        for u in self.N_x:
            mismatch_terms.append(
                1.0 - x[u]
                if float(design["x"].get(u, 0.0)) > 0.5
                else x[u]
            )
        for arc in self.AY:
            mismatch_terms.append(
                1.0 - y[arc]
                if float(design["y"].get(arc, 0.0)) > 0.5
                else y[arc]
            )
        for i in self.H:
            for c in range(len(config.MU_HUB)):
                mismatch_terms.append(
                    1.0 - z[i, c]
                    if float(design["z"].get((i, c), 0.0)) > 0.5
                    else z[i, c]
                )
        mismatch = gp.quicksum(mismatch_terms)
        big_m = max(
            0.0,
            self._global_operating_ub - float(net_upper_bound),
        )
        self.cut_count += 1
        self.master.addConstr(
            eta - float(config.COST_DRONE) * gamma
            <= float(net_upper_bound) + big_m * mismatch,
            name=f"{prefix}_{self.cut_count}",
        )
        self.flow_cut_stats.network_net_profit_cuts += 1

    # ------------------------------------------------------------------
    # Connectivity and swap-reachability combinatorial cuts
    # ------------------------------------------------------------------

    def _potential_od_profit(self, i: Node, j: Node) -> float:
        revenue = float(getattr(config, "ORDER_REVENUE_COEF", 0.0))
        demand = max(0.0, float(self.inst.h.get((i, j), 0.0)))
        return revenue * demand

    def _active_aggregate_graph(
        self,
        design: Mapping[str, object],
        *,
        swap_aware: bool,
    ) -> nx.DiGraph:
        graph = nx.DiGraph()
        graph.add_nodes_from(self.HLS)
        y = design["y"]
        for u, v in self.A_hat:
            if float(y.get((u, v), 0.0)) <= 0.5:
                continue
            if swap_aware and not self._route_is_available(y, u, v):
                continue
            graph.add_edge(u, v)
        graph.add_edges_from(self.A_virtual)
        return graph

    def _route_requirements(self, u: Node, v: Node, k: Node) -> Tuple[Arc, ...]:
        if k in self.E:
            return ((u, v), (u, k), (k, v))
        return ((u, v),)

    def _route_is_available(
        self, y: Mapping[Arc, float], u: Node, v: Node
    ) -> bool:
        for k in self.route_options.get((u, v), []):
            if all(float(y.get(arc, 0.0)) > 0.5 for arc in self._route_requirements(u, v, k)):
                return True
        return False

    def _missing_route_arcs(
        self, y: Mapping[Arc, float], u: Node, v: Node
    ) -> set[Arc]:
        missing: set[Arc] = set()
        options = self.route_options.get((u, v), [])
        for k in options:
            requirements = self._route_requirements(u, v, k)
            if all(float(y.get(arc, 0.0)) > 0.5 for arc in requirements):
                return set()
            missing.update(
                arc for arc in requirements if float(y.get(arc, 0.0)) <= 0.5
            )
        return missing

    def _add_service_reachability_cut(
        self,
        pair: Pair,
        missing_arcs: Iterable[Arc],
        *,
        prefix: str,
        signature_store: set[Tuple[Pair, Tuple[Arc, ...]]],
    ) -> bool:
        assert self.master is not None
        missing = tuple(sorted(set(missing_arcs)))
        signature = (pair, missing)
        if signature in signature_store:
            return False
        signature_store.add(signature)
        y = self.master_vars["y"]
        service_possible = self.master_vars["service_possible"]
        repair = gp.quicksum(y[arc] for arc in missing if arc in y)
        self.cut_count += 1
        self.master.addConstr(
            service_possible[pair] <= repair,
            name=f"{prefix}_{self.cut_count}",
        )
        return True

    def add_topology_connectivity_cuts(
        self, design: Mapping[str, object]
    ) -> int:
        """Add profit-loss cuts for OD flows lacking an aggregate return path."""
        graph = self._active_aggregate_graph(design, swap_aware=False)
        y = design["y"]
        service_possible = self.master_vars["service_possible"]
        added = 0
        for i, j in sorted(
            self.A_HH,
            key=lambda pair: self._potential_od_profit(*pair),
            reverse=True,
        ):
            profit = self._potential_od_profit(i, j)
            if profit <= 1e-9 or float(service_possible[i, j].X) <= 0.5:
                continue
            if float(y.get((i, j), 0.0)) <= 0.5:
                # The static service_possible <= y_ij constraint already
                # handles this case.
                continue
            else:
                reachable = (
                    {j} | nx.descendants(graph, j)
                    if j in graph
                    else {j}
                )
                if i in reachable:
                    continue
                missing = tuple(
                    sorted(
                        (u, v)
                        for u, v in self.A_hat
                        if u in reachable and v not in reachable
                    )
                )
            if self._add_service_reachability_cut(
                (i, j),
                missing,
                prefix="topology_profit_loss",
                signature_store=self._topology_cut_signatures,
            ):
                added += 1
                if added >= self.max_combinatorial_cuts_per_iteration:
                    break
        self.flow_cut_stats.topology_cuts += added
        return added

    def add_swap_reachability_cuts(
        self, design: Mapping[str, object]
    ) -> int:
        """Add cuts for topology-feasible but direct/swap-infeasible OD flow."""
        topology_graph = self._active_aggregate_graph(
            design, swap_aware=False
        )
        swap_graph = self._active_aggregate_graph(design, swap_aware=True)
        y = design["y"]
        service_possible = self.master_vars["service_possible"]
        added = 0
        for i, j in sorted(
            self.A_HH,
            key=lambda pair: self._potential_od_profit(*pair),
            reverse=True,
        ):
            profit = self._potential_od_profit(i, j)
            if profit <= 1e-9 or float(service_possible[i, j].X) <= 0.5:
                continue

            top_reachable = (
                {j} | nx.descendants(topology_graph, j)
                if j in topology_graph
                else {j}
            )
            if (
                float(y.get((i, j), 0.0)) <= 0.5
                or i not in top_reachable
            ):
                # This OD belongs to the topology family, not the swap family.
                continue

            missing = self._missing_route_arcs(y, i, j)
            if not missing:
                reachable = (
                    {j} | nx.descendants(swap_graph, j)
                    if j in swap_graph
                    else {j}
                )
                if i in reachable:
                    continue
                for u, v in self.A_hat:
                    if u not in reachable or v in reachable:
                        continue
                    missing.update(self._missing_route_arcs(y, u, v))

            if self._add_service_reachability_cut(
                (i, j),
                missing,
                prefix="swap_reachability_profit_loss",
                signature_store=self._swap_cut_signatures,
            ):
                added += 1
                if added >= self.max_combinatorial_cuts_per_iteration:
                    break
        self.flow_cut_stats.swap_reachability_cuts += added
        return added

    # ------------------------------------------------------------------
    # Lagrangian-relaxation warm start
    # ------------------------------------------------------------------

    def _build_lr_design_subproblem(
        self,
        lambda_o: Mapping[Pair, float],
        lambda_d: Mapping[Pair, float],
        lambda_a: Mapping[Pair, float],
    ) -> Tuple[gp.Model, Dict[str, object]]:
        """Build the first-stage side of the LR service-link decomposition."""
        m = gp.Model("MLND_RegimeII_LR_Design")
        m.Params.OutputFlag = int(getattr(config, "BENDERS_LR_LOG", 0))
        m.Params.Threads = 1
        m.Params.Seed = int(getattr(config, "BENDERS_RANDOM_SEED", 0))
        C = range(len(config.MU_HUB))
        mu_c = list(config.MU_HUB)
        tau_h = float(config.TAU_H)

        x = m.addVars(self.N_x, vtype=GRB.BINARY, name="x")
        y = m.addVars(self.AY, vtype=GRB.BINARY, name="y")
        z = m.addVars(self.H, C, vtype=GRB.BINARY, name="z")

        objective = gp.quicksum(
            (
                float(lambda_o.get((i, j), 0.0)) * x[i]
                + float(lambda_d.get((i, j), 0.0)) * x[j]
                + float(lambda_a.get((i, j), 0.0)) * y[i, j]
            )
            for i, j in self.A_HH
            if (i, j) in y
        )
        objective -= gp.quicksum(
            float(self.inst.f.get(l, config.COST_BASE)) * x[l] for l in self.L
        )
        objective -= gp.quicksum(
            float(getattr(config, "COST_HUB_FIXED", 0.0)) * x[i]
            for i in self.H
        )
        objective -= gp.quicksum(
            float(self.inst.f.get(k, config.COST_SWAPPING)) * x[k]
            for k in self.E
        )
        objective -= gp.quicksum(
            float(config.COST_HUB[c]) * z[i, c] for i in self.H for c in C
        )
        objective -= gp.quicksum(
            self.arc_cost[u, v] * y[u, v] for u, v in self.AY
        )
        m.setObjective(objective, GRB.MAXIMIZE)

        for i in self.H:
            assigned = [l for l, h in self.A_LH if h == i]
            m.addConstr(
                gp.quicksum(y[l, i] for l in assigned if (l, i) in y) == x[i]
            )
            m.addConstr(gp.quicksum(z[i, c] for c in C) == x[i])
            m.addConstr(
                gp.quicksum(float(mu_c[c]) * z[i, c] for c in C)
                >= x[i] / tau_h
            )
        for l, i in self.A_LH:
            m.addConstr(y[l, i] <= x[l])
        for u, v in self.AY:
            if (u, v) in self.A_LH:
                continue
            m.addConstr(y[u, v] <= self._node_activation_expr({"x": x}, u))
            m.addConstr(y[u, v] <= self._node_activation_expr({"x": x}, v))
        return m, {"x": x, "y": y, "z": z}

    def _nearest_base(self, hub: Node) -> Optional[Node]:
        bases = [l for l, h in self.A_LH if h == hub]
        if not bases:
            return None
        return min(bases, key=lambda l: self.inst.get_dist(l, hub))

    def _cheapest_route(self, u: Node, v: Node) -> Optional[Node]:
        options = self.route_options.get((u, v), [])
        if not options:
            return None
        return min(options, key=lambda k: self.t[u, v, k])

    def _recovery_route(self, u: Node, v: Node) -> Optional[Node]:
        """Prefer a battery-reset route during LR primal recovery."""
        options = self.route_options.get((u, v), [])
        if not options:
            return None
        swap_options = [k for k in options if k in self.E]
        candidate_options = swap_options or options
        return min(candidate_options, key=lambda k: self.t[u, v, k])

    def _recover_lr_design(
        self,
        raw_design: Mapping[str, object],
        selected_pairs: Sequence[Pair],
        *,
        pair_limit: Optional[int] = None,
        consolidate_network: bool = True,
        prefer_swap_routes: bool = True,
    ) -> Dict[str, object]:
        """Repair an LR design without solving the original conic model."""
        C = range(len(config.MU_HUB))
        # Start from a clean first-stage design.  The LR design subproblem may
        # select an HH arc that has no physical route because the route-linking
        # constraints were deliberately relaxed.  Copying those raw arcs would
        # defeat the purpose of primal recovery.
        x = {u: 0.0 for u in self.N_x}
        y = {arc: 0.0 for arc in self.AY}
        z = {(i, c): 0.0 for i in self.H for c in C}

        # Keep the recovery bounded and driven by the most valuable LR pairs.
        ranked_pairs = sorted(
            selected_pairs,
            key=lambda pair: self._potential_od_profit(*pair),
            reverse=True,
        )
        if pair_limit is None:
            pair_limit = int(
                getattr(config, "BENDERS_LR_RECOVERY_PAIRS", 20)
            )
        ranked_pairs = ranked_pairs[: max(1, int(pair_limit))]

        return_graph = nx.DiGraph()
        return_graph.add_nodes_from(self.HLS)
        for u, v in [*self.A_SS, *self.A_SL]:
            route = self._recovery_route(u, v)
            if route is None:
                continue
            return_graph.add_edge(u, v, weight=float(self.t[u, v, route]))
        return_graph.add_edges_from(
            (u, v, {"weight": 0.0}) for u, v in self.A_virtual
        )

        used_pairs: List[Pair] = []
        pair_paths: Dict[Pair, List[Tuple[List[Arc], float]]] = {}
        used_aggregate_arcs: set[Arc] = set()
        for i, j in ranked_pairs:
            if self._recovery_route(i, j) is None:
                continue
            endpoints: List[Tuple[Node, float]] = []
            p_i = self._p_chain(i)
            if p_i > 1e-9:
                endpoints.append((self._hub_pool(i), p_i))
            if 1.0 - p_i > 1e-9:
                base = self._nearest_base(i)
                if base is not None:
                    endpoints.append((base, 1.0 - p_i))
            recovered_paths: List[Tuple[List[Arc], float]] = []
            for endpoint, fraction in endpoints:
                try:
                    node_path = nx.shortest_path(
                        return_graph, j, endpoint, weight="weight"
                    )
                except (nx.NetworkXNoPath, nx.NodeNotFound):
                    recovered_paths = []
                    break
                recovered_paths.append(
                    (list(zip(node_path[:-1], node_path[1:])), fraction)
                )
            if not recovered_paths:
                continue
            used_pairs.append((i, j))
            pair_paths[i, j] = recovered_paths
            used_aggregate_arcs.add((i, j))
            for path_arcs, _ in recovered_paths:
                used_aggregate_arcs.update(path_arcs)

        if not used_pairs and self.A_HH:
            for i, j in sorted(
                self.A_HH,
                key=lambda pair: self._potential_od_profit(*pair),
                reverse=True,
            ):
                if self._recovery_route(i, j) is None:
                    continue
                endpoints = []
                p_i = self._p_chain(i)
                if p_i > 1e-9:
                    endpoints.append((self._hub_pool(i), p_i))
                if 1.0 - p_i > 1e-9:
                    base = self._nearest_base(i)
                    if base is not None:
                        endpoints.append((base, 1.0 - p_i))
                recovered_paths = []
                for endpoint, fraction in endpoints:
                    try:
                        node_path = nx.shortest_path(
                            return_graph, j, endpoint, weight="weight"
                        )
                    except (nx.NetworkXNoPath, nx.NodeNotFound):
                        recovered_paths = []
                        break
                    recovered_paths.append(
                        (list(zip(node_path[:-1], node_path[1:])), fraction)
                    )
                if not recovered_paths:
                    continue
                used_pairs = [(i, j)]
                pair_paths[i, j] = recovered_paths
                used_aggregate_arcs.add((i, j))
                for path_arcs, _ in recovered_paths:
                    used_aggregate_arcs.update(path_arcs)
                break

        touched_hubs = set()
        required_bases = set()
        for arc in used_aggregate_arcs:
            for node in arc:
                if node in self.H:
                    touched_hubs.add(node)
                elif node in self.S:
                    touched_hubs.add(self.inst.s_to_h[node])
                elif node in self.L:
                    required_bases.add(node)
        touched_hubs.update(node for pair in used_pairs for node in pair)

        arc_flow_weight = {arc: 0.0 for arc in used_aggregate_arcs}
        for i, j in used_pairs:
            demand = float(self.inst.h.get((i, j), 0.0))
            arc_flow_weight[i, j] = arc_flow_weight.get((i, j), 0.0) + demand
            for path_arcs, fraction in pair_paths.get((i, j), []):
                for arc in path_arcs:
                    arc_flow_weight[arc] = (
                        arc_flow_weight.get(arc, 0.0) + fraction * demand
                    )

        recovery_model = gp.Model("MLND_RegimeII_LR_PrimalRecovery")
        recovery_model.Params.OutputFlag = 0
        recovery_model.Params.Threads = 1
        recovery_model.Params.Seed = int(
            getattr(config, "BENDERS_RANDOM_SEED", 0)
        )
        recovery_model.Params.TimeLimit = float(
            getattr(config, "BENDERS_LR_RECOVERY_MILP_TIME_LIMIT", 2.0)
        )
        base_open = recovery_model.addVars(self.L, vtype=GRB.BINARY, name="base")
        swap_open = recovery_model.addVars(self.E, vtype=GRB.BINARY, name="swap")
        assignment_keys = [
            (l, h) for l, h in self.A_LH if h in touched_hubs
        ]
        assignment = recovery_model.addVars(
            assignment_keys, vtype=GRB.BINARY, name="assign"
        )

        def recovery_options(u: Node, v: Node) -> List[Node]:
            options = list(self.route_options.get((u, v), []))
            if not prefer_swap_routes:
                return options
            swap_options = [option for option in options if option in self.E]
            return swap_options or options

        route_choice_keys = [
            (u, v, k)
            for u, v in used_aggregate_arcs
            if (u, v) not in self.A_virtual
            for k in recovery_options(u, v)
        ]
        route_choice = recovery_model.addVars(
            route_choice_keys, vtype=GRB.BINARY, name="route"
        )
        physical_arcs = sorted(
            {
                arc
                for u, v, k in route_choice_keys
                for arc in self._route_requirements(u, v, k)
                if arc in self.AY
            }
            | set(assignment_keys)
        )
        physical_open = recovery_model.addVars(
            physical_arcs, vtype=GRB.BINARY, name="physical"
        )

        for hub in touched_hubs:
            feasible = [
                assignment[l, h]
                for l, h in assignment_keys
                if h == hub
            ]
            if feasible:
                recovery_model.addConstr(gp.quicksum(feasible) == 1.0)
        for l, h in assignment_keys:
            recovery_model.addConstr(assignment[l, h] <= base_open[l])
            recovery_model.addConstr(physical_open[l, h] == assignment[l, h])
        for base in required_bases:
            recovery_model.addConstr(base_open[base] == 1.0)
        for l, h in used_aggregate_arcs:
            if (l, h) in assignment and (l, h) in self.A_LH:
                recovery_model.addConstr(assignment[l, h] == 1.0)

        for u, v in used_aggregate_arcs:
            if (u, v) in self.A_virtual:
                continue
            choices = [
                route_choice[u, v, k]
                for k in recovery_options(u, v)
                if (u, v, k) in route_choice
            ]
            if choices:
                recovery_model.addConstr(gp.quicksum(choices) == 1.0)
        for u, v, k in route_choice_keys:
            choice = route_choice[u, v, k]
            for arc in self._route_requirements(u, v, k):
                if arc in physical_open:
                    recovery_model.addConstr(choice <= physical_open[arc])
            if k in self.E:
                recovery_model.addConstr(choice <= swap_open[k])
        for arc in physical_arcs:
            supporting = [
                route_choice[u, v, k]
                for u, v, k in route_choice_keys
                if arc in self._route_requirements(u, v, k)
            ]
            if arc in assignment:
                supporting.append(assignment[arc])
            if supporting:
                recovery_model.addConstr(
                    physical_open[arc] <= gp.quicksum(supporting)
                )

        recovery_objective = gp.quicksum(
            float(self.inst.f.get(l, config.COST_BASE)) * base_open[l]
            for l in self.L
        )
        recovery_objective += gp.quicksum(
            float(self.inst.f.get(k, config.COST_SWAPPING)) * swap_open[k]
            for k in self.E
        )
        recovery_objective += gp.quicksum(
            self.arc_cost[arc] * physical_open[arc]
            for arc in physical_arcs
        )
        recovery_objective += gp.quicksum(
            (
                self.flight_cost[u, v, k]
                + float(config.COST_DRONE) * self.t[u, v, k]
            )
            * arc_flow_weight.get((u, v), 0.0)
            * route_choice[u, v, k]
            for u, v, k in route_choice_keys
        )
        recovery_model.setObjective(recovery_objective, GRB.MINIMIZE)
        recovery_model.optimize()

        if recovery_model.SolCount > 0 and consolidate_network:
            for hub in touched_hubs:
                x[hub] = 1.0
            for l in self.L:
                x[l] = float(base_open[l].X > 0.5)
            for k in self.E:
                x[k] = float(swap_open[k].X > 0.5)
            for arc in physical_arcs:
                y[arc] = float(physical_open[arc].X > 0.5)
        else:
            for hub in touched_hubs:
                x[hub] = 1.0
                base = self._nearest_base(hub)
                if base is not None:
                    x[base] = 1.0
                    y[base, hub] = 1.0
            for u, v in used_aggregate_arcs:
                if (u, v) in y:
                    y[u, v] = 1.0
                route = self._recovery_route(u, v)
                if route in self.E:
                    x[route] = 1.0
                    if (u, route) in y:
                        y[u, route] = 1.0
                    if (route, v) in y:
                        y[route, v] = 1.0

        incoming = {i: 0.0 for i in self.H}
        for i, j in used_pairs:
            incoming[j] += float(self.inst.h.get((i, j), 0.0))
        for i in self.H:
            for c in C:
                z[i, c] = 0.0
            if x.get(i, 0.0) <= 0.5:
                continue
            required = incoming[i] + 1.0 / float(config.TAU_H)
            level = len(config.MU_HUB) - 1
            for c, mu in enumerate(config.MU_HUB):
                if float(mu) >= required:
                    level = c
                    break
            z[i, level] = 1.0

        total_time = 0.0
        for i, j in used_pairs:
            demand = float(self.inst.h.get((i, j), 0.0))
            selected_loaded_routes = [
                k
                for k in self.route_options.get((i, j), [])
                if (i, j, k) in route_choice
                and recovery_model.SolCount > 0
                and route_choice[i, j, k].X > 0.5
            ]
            loaded_route = (
                selected_loaded_routes[0]
                if selected_loaded_routes
                else self._recovery_route(i, j)
            )
            if loaded_route is not None:
                total_time += demand * float(self.t[i, j, loaded_route])
            for path_arcs, fraction in pair_paths.get((i, j), []):
                for u, v in path_arcs:
                    if (u, v) in self.A_virtual:
                        continue
                    selected_routes = [
                        k
                        for k in self.route_options.get((u, v), [])
                        if (u, v, k) in route_choice
                        and recovery_model.SolCount > 0
                        and route_choice[u, v, k].X > 0.5
                    ]
                    route = (
                        selected_routes[0]
                        if selected_routes
                        else self._recovery_route(u, v)
                    )
                    if route is not None:
                        total_time += (
                            fraction * demand * float(self.t[u, v, route])
                        )
        gamma = float(max(0, math.ceil(1.50 * total_time)))
        return {"x": x, "y": y, "z": z, "Gamma": gamma}

    @staticmethod
    def _design_signature(design: Mapping[str, object]) -> Tuple[int, ...]:
        x = tuple(int(float(v) > 0.5) for _, v in sorted(design["x"].items()))
        y = tuple(int(float(v) > 0.5) for _, v in sorted(design["y"].items()))
        z = tuple(int(float(v) > 0.5) for _, v in sorted(design["z"].items()))
        return x + y + z + (int(round(float(design["Gamma"]))),)

    def _prune_design_from_estimator(
        self,
        design: Mapping[str, object],
        snapshot: Mapping[str, object],
    ) -> Dict[str, object]:
        """Project a swap-aware LP solution to a compact first-stage design.

        This is a primal-recovery operation.  It uses only the linear
        estimator solution and first-stage logic; it never calls the exact
        SOCP or the monolithic model.
        """
        flow_tol = float(
            getattr(config, "BENDERS_LR_PRUNE_FLOW_TOL", 1e-7)
        )
        psi = snapshot.get("psi", {})
        varphi = snapshot.get("varphi", {})
        x = {u: 0.0 for u in self.N_x}
        y = {arc: 0.0 for arc in self.AY}
        z = {
            (i, c): 0.0
            for i in self.H
            for c in range(len(config.MU_HUB))
        }

        used_aggregate = {
            (u, v)
            for (u, v), value in psi.items()
            if float(value) > flow_tol and (u, v) in self.A_hat
        }
        used_routes = {
            (u, v, k)
            for (u, v, k), value in varphi.items()
            if float(value) > flow_tol
        }
        used_physical = set(used_aggregate)
        used_swaps = set()
        for u, v, k in used_routes:
            used_physical.update(self._route_requirements(u, v, k))
            if k in self.E:
                used_swaps.add(k)

        used_hubs = set()
        used_bases = set()
        for u, v in used_aggregate:
            for node in (u, v):
                if node in self.H:
                    used_hubs.add(node)
                elif node in self.S:
                    used_hubs.add(self.inst.s_to_h[node])
                elif node in self.L:
                    used_bases.add(node)

        original_y = design["y"]
        for hub in sorted(used_hubs):
            existing = [
                l
                for l, h in self.A_LH
                if h == hub and float(original_y.get((l, hub), 0.0)) > 0.5
            ]
            feasible = existing or [
                l for l, h in self.A_LH if h == hub
            ]
            if not feasible:
                continue
            base = min(feasible, key=lambda l: self.inst.get_dist(l, hub))
            used_bases.add(base)
            y[base, hub] = 1.0

        for arc in used_physical:
            if arc in y:
                y[arc] = 1.0
        for hub in used_hubs:
            x[hub] = 1.0
        for base in used_bases:
            x[base] = 1.0
        for swap in used_swaps:
            x[swap] = 1.0

        # Remove physical arcs whose endpoints were not retained.
        def node_open(node: Node) -> bool:
            if node in self.S:
                return x.get(self.inst.s_to_h[node], 0.0) > 0.5
            return x.get(node, 0.0) > 0.5

        for u, v in self.AY:
            if y[u, v] > 0.5 and (not node_open(u) or not node_open(v)):
                y[u, v] = 0.0

        incoming = {
            i: sum(
                float(value)
                for (u, v), value in psi.items()
                if v == i
            )
            for i in self.H
        }
        for hub in used_hubs:
            required = incoming[hub] + 1.0 / float(config.TAU_H)
            level = len(config.MU_HUB) - 1
            for c, mu in enumerate(config.MU_HUB):
                if float(mu) >= required - 1e-7:
                    level = c
                    break
            z[hub, level] = 1.0

        total_time_lb = max(
            0.0, float(snapshot.get("total_time_lb", 0.0))
        )
        gamma = float(max(0, math.ceil(total_time_lb)))
        return {"x": x, "y": y, "z": z, "Gamma": gamma}

    @staticmethod
    def _copy_design(design: Mapping[str, object]) -> Dict[str, object]:
        return {
            "x": dict(design["x"]),
            "y": dict(design["y"]),
            "z": dict(design["z"]),
            "Gamma": float(design.get("Gamma", 0.0)),
        }

    def _drop_facility_incident_arcs(
        self,
        design: Dict[str, object],
        node: Node,
    ) -> None:
        related = {node}
        if node in self.H:
            related.add(self._hub_pool(node))
        for u, v in self.AY:
            if u in related or v in related:
                design["y"][u, v] = 0.0

    def _reroute_active_aggregate_arcs(
        self,
        design: Dict[str, object],
        *,
        forbidden_swaps: Optional[set[Node]] = None,
    ) -> None:
        """Repair route readiness after a compound facility move."""
        forbidden_swaps = forbidden_swaps or set()
        x = design["x"]
        y = design["y"]
        for u, v in self.A_hat:
            if float(y.get((u, v), 0.0)) <= 0.5:
                continue
            available = []
            for k in self.route_options.get((u, v), []):
                if k in forbidden_swaps:
                    continue
                requirements = self._route_requirements(u, v, k)
                if all(float(y.get(arc, 0.0)) > 0.5 for arc in requirements):
                    available.append(k)
            if available:
                continue

            options = [
                k
                for k in self.route_options.get((u, v), [])
                if k not in forbidden_swaps
            ]
            direct = [k for k in options if k not in self.E]
            existing_swaps = [
                k
                for k in options
                if k in self.E and float(x.get(k, 0.0)) > 0.5
            ]
            candidates = direct or existing_swaps
            if not candidates:
                y[u, v] = 0.0
                continue
            route = min(candidates, key=lambda k: self.t[u, v, k])
            for arc in self._route_requirements(u, v, route):
                if arc in y:
                    y[arc] = 1.0
            if route in self.E:
                x[route] = 1.0

    def _open_route_bundle(
        self,
        design: Dict[str, object],
        u: Node,
        v: Node,
        k: Node,
        *,
        replace_existing: bool = False,
    ) -> bool:
        """Open one direct/swap route bundle in a first-stage design."""
        requirements = self._route_requirements(u, v, k)
        if any(arc not in design["y"] for arc in requirements):
            return False

        y = design["y"]
        if replace_existing:
            old_requirements = {
                arc
                for option in self.route_options.get((u, v), [])
                if all(
                    float(y.get(item, 0.0)) > 0.5
                    for item in self._route_requirements(u, v, option)
                )
                for arc in self._route_requirements(u, v, option)
            }
            for arc in old_requirements - set(requirements):
                if arc != (u, v):
                    y[arc] = 0.0

        for arc in requirements:
            y[arc] = 1.0
        if k in self.E:
            design["x"][k] = 1.0
        return True

    def _repair_first_stage_logic(
        self,
        design: Mapping[str, object],
    ) -> Optional[Dict[str, object]]:
        """Repair only first-stage MILP logic after a local-search move."""
        repaired = self._copy_design(design)
        x = repaired["x"]
        y = repaired["y"]
        z = repaired["z"]
        for u in self.N_x:
            x[u] = float(float(x.get(u, 0.0)) > 0.5)
        for arc in self.AY:
            y[arc] = float(float(y.get(arc, 0.0)) > 0.5)

        open_bases = {l for l in self.L if x[l] > 0.5}
        for hub in self.H:
            if x[hub] <= 0.5:
                for c in range(len(config.MU_HUB)):
                    z[hub, c] = 0.0
                self._drop_facility_incident_arcs(repaired, hub)
                continue

            assigned = [
                l
                for l, h in self.A_LH
                if h == hub and y.get((l, hub), 0.0) > 0.5
                and x.get(l, 0.0) > 0.5
            ]
            if assigned:
                base = min(assigned, key=lambda l: self.inst.get_dist(l, hub))
            else:
                feasible_open = [
                    l
                    for l, h in self.A_LH
                    if h == hub and l in open_bases
                ]
                if not feasible_open:
                    feasible = [l for l, h in self.A_LH if h == hub]
                    if not feasible:
                        return None
                    base = min(
                        feasible, key=lambda l: self.inst.get_dist(l, hub)
                    )
                    x[base] = 1.0
                    open_bases.add(base)
                else:
                    base = min(
                        feasible_open,
                        key=lambda l: self.inst.get_dist(l, hub),
                    )
            for l, h in self.A_LH:
                if h == hub:
                    y[l, hub] = float(l == base)

            selected_levels = [
                c
                for c in range(len(config.MU_HUB))
                if float(z.get((hub, c), 0.0)) > 0.5
            ]
            level = selected_levels[0] if selected_levels else 0
            min_mu = 1.0 / float(config.TAU_H)
            while (
                level < len(config.MU_HUB) - 1
                and float(config.MU_HUB[level]) < min_mu
            ):
                level += 1
            for c in range(len(config.MU_HUB)):
                z[hub, c] = float(c == level)

        def is_open(node: Node) -> bool:
            if node in self.S:
                return x.get(self.inst.s_to_h[node], 0.0) > 0.5
            return x.get(node, 0.0) > 0.5

        for u, v in self.AY:
            if y[u, v] > 0.5 and (not is_open(u) or not is_open(v)):
                y[u, v] = 0.0

        # Close base/swap facilities made redundant by the move.
        for base in self.L:
            if not any(
                y.get((base, hub), 0.0) > 0.5
                for l, hub in self.A_LH
                if l == base
            ) and not any(
                y.get((u, v), 0.0) > 0.5 and (u == base or v == base)
                for u, v in self.AY
            ):
                x[base] = 0.0
        for swap in self.E:
            if not any(
                y.get((u, v), 0.0) > 0.5 and (u == swap or v == swap)
                for u, v in self.AY
            ):
                x[swap] = 0.0
        repaired["Gamma"] = float(max(0, round(repaired["Gamma"])))
        return repaired

    def _network_net_score(
        self,
        design: Mapping[str, object],
        *,
        label: str,
    ) -> Tuple[float, Optional[Dict[str, object]]]:
        estimate = self.solve_swap_network_net_estimator(design, label=label)
        if estimate.obj_value is None:
            return -math.inf, None
        snapshot = self._estimator_snapshots.get(label, {})
        gamma = float(snapshot.get("gamma_opt") or 0.0)
        candidate = self._copy_design(design)
        candidate["Gamma"] = float(max(0, round(gamma)))
        non_drone_fixed = self._fixed_cost_value(candidate) - (
            float(config.COST_DRONE) * candidate["Gamma"]
        )
        return float(estimate.obj_value) - non_drone_fixed, candidate

    def _network_tabu_refinement(
        self,
        seeds: Sequence[Mapping[str, object]],
        *,
        deadline: float,
        candidate_sink: Dict[Tuple[int, ...], Dict[str, object]],
        score_sink: Dict[Tuple[int, ...], float],
    ) -> None:
        """LR-guided Tabu on first-stage networks using LP net bounds only."""
        if not seeds or time.perf_counter() >= deadline:
            return
        scored_seeds = []
        for seed_index, seed in enumerate(seeds, 1):
            if time.perf_counter() >= deadline:
                break
            repaired = self._repair_first_stage_logic(seed)
            if repaired is None:
                continue
            score, candidate = self._network_net_score(
                repaired, label=f"network_tabu_seed_{seed_index}"
            )
            if candidate is not None:
                scored_seeds.append((score, candidate))
        if not scored_seeds:
            return
        scored_seeds.sort(key=lambda item: item[0], reverse=True)
        current_score, current = scored_seeds[0]
        best_score, best = current_score, current
        tabu_until: Dict[Tuple[str, object], int] = {}
        tenure = max(
            1, int(getattr(config, "BENDERS_NETWORK_TABU_TENURE", 5))
        )
        max_iterations = max(
            1, int(getattr(config, "BENDERS_NETWORK_TABU_ITERATIONS", 20))
        )

        for iteration in range(1, max_iterations + 1):
            if time.perf_counter() >= deadline:
                break
            x = current["x"]
            y = current["y"]
            z = current["z"]
            moves: List[Tuple[Tuple[str, object], Dict[str, object]]] = []

            for swap in self.E:
                if float(x.get(swap, 0.0)) <= 0.5:
                    continue
                trial = self._copy_design(current)
                trial["x"][swap] = 0.0
                self._drop_facility_incident_arcs(trial, swap)
                self._reroute_active_aggregate_arcs(
                    trial, forbidden_swaps={swap}
                )
                moves.append((("drop_swap", swap), trial))

            for base in self.L:
                if float(x.get(base, 0.0)) <= 0.5:
                    continue
                trial = self._copy_design(current)
                trial["x"][base] = 0.0
                self._drop_facility_incident_arcs(trial, base)
                moves.append((("drop_base", base), trial))

            hub_candidates = sorted(
                [h for h in self.H if float(x.get(h, 0.0)) > 0.5],
                key=lambda h: sum(
                    float(self.inst.h.get((h, j), 0.0))
                    + float(self.inst.h.get((j, h), 0.0))
                    for j in self.H
                    if j != h
                ),
            )[: int(getattr(config, "BENDERS_NETWORK_TABU_HUB_WIDTH", 8))]
            for hub in hub_candidates:
                trial = self._copy_design(current)
                trial["x"][hub] = 0.0
                self._drop_facility_incident_arcs(trial, hub)
                moves.append((("drop_hub", hub), trial))

            active_non_assignment = [
                arc
                for arc in self.AY
                if float(y.get(arc, 0.0)) > 0.5
                and arc not in self.A_LH
            ]
            active_non_assignment.sort(
                key=lambda arc: self.arc_cost.get(arc, 0.0),
                reverse=True,
            )
            for arc in active_non_assignment[
                : int(getattr(config, "BENDERS_NETWORK_TABU_ARC_WIDTH", 15))
            ]:
                trial = self._copy_design(current)
                trial["y"][arc] = 0.0
                moves.append((("drop_arc", arc), trial))

            base_reassignments = []
            for hub in self.H:
                if float(x.get(hub, 0.0)) <= 0.5:
                    continue
                current_bases = {
                    l
                    for l, h in self.A_LH
                    if h == hub and float(y.get((l, hub), 0.0)) > 0.5
                }
                for base, assigned_hub in self.A_LH:
                    if assigned_hub != hub or base in current_bases:
                        continue
                    route_times = [
                        float(self.t[base, hub, k])
                        for k in self.route_options.get((base, hub), [])
                    ]
                    if not route_times:
                        continue
                    base_reassignments.append(
                        (min(route_times), hub, base)
                    )
            base_reassignments.sort()
            for _, hub, base in base_reassignments[
                : int(
                    getattr(
                        config, "BENDERS_NETWORK_TABU_BASE_ASSIGN_WIDTH", 12
                    )
                )
            ]:
                trial = self._copy_design(current)
                for old_base, assigned_hub in self.A_LH:
                    if assigned_hub == hub:
                        trial["y"][old_base, hub] = 0.0
                trial["x"][base] = 1.0
                trial["y"][base, hub] = 1.0
                moves.append((("reassign_base", (hub, base)), trial))

            route_moves = []
            for u, v in self.A_hat:
                if float(y.get((u, v), 0.0)) <= 0.5:
                    continue
                active_options = [
                    k
                    for k in self.route_options.get((u, v), [])
                    if all(
                        float(y.get(arc, 0.0)) > 0.5
                        for arc in self._route_requirements(u, v, k)
                    )
                ]
                active_time = min(
                    (float(self.t[u, v, k]) for k in active_options),
                    default=math.inf,
                )
                for k in self.route_options.get((u, v), []):
                    if k in active_options:
                        continue
                    route_moves.append(
                        (
                            float(self.t[u, v, k]) - active_time,
                            u,
                            v,
                            k,
                        )
                    )
            route_moves.sort(
                key=lambda item: (
                    item[0],
                    0 if item[3] in self.E else 1,
                    item[1],
                    item[2],
                    item[3],
                )
            )
            for _, u, v, k in route_moves[
                : int(
                    getattr(
                        config, "BENDERS_NETWORK_TABU_ROUTE_WIDTH", 16
                    )
                )
            ]:
                for replace_existing in (False, True):
                    trial = self._copy_design(current)
                    if not self._open_route_bundle(
                        trial,
                        u,
                        v,
                        k,
                        replace_existing=replace_existing,
                    ):
                        continue
                    move_kind = (
                        "replace_route" if replace_existing else "add_route"
                    )
                    moves.append(
                        ((move_kind, (u, v, k)), trial)
                    )

            od_expansions = []
            for i, j in self.A_HH:
                if (
                    float(y.get((i, j), 0.0)) > 0.5
                    or float(x.get(i, 0.0)) <= 0.5
                    or float(x.get(j, 0.0)) <= 0.5
                ):
                    continue
                for k in self.route_options.get((i, j), []):
                    od_expansions.append(
                        (
                            -self._potential_od_profit(i, j)
                            + float(self.flight_cost[i, j, k]),
                            i,
                            j,
                            k,
                        )
                    )
            od_expansions.sort()
            for _, i, j, k in od_expansions[
                : int(
                    getattr(
                        config, "BENDERS_NETWORK_TABU_OD_EXPAND_WIDTH", 12
                    )
                )
            ]:
                trial = self._copy_design(current)
                if self._open_route_bundle(trial, i, j, k):
                    moves.append((("add_od_route", (i, j, k)), trial))

            for hub in self.H:
                levels = [
                    c
                    for c in range(len(config.MU_HUB))
                    if float(z.get((hub, c), 0.0)) > 0.5
                ]
                if not levels:
                    continue
                level = levels[0]
                if level > 0:
                    trial = self._copy_design(current)
                    trial["z"][hub, level] = 0.0
                    trial["z"][hub, level - 1] = 1.0
                    moves.append((("lower_capacity", hub), trial))
                if level + 1 < len(config.MU_HUB):
                    trial = self._copy_design(current)
                    trial["z"][hub, level] = 0.0
                    trial["z"][hub, level + 1] = 1.0
                    moves.append((("raise_capacity", hub), trial))

            chosen = None
            chosen_move = None
            chosen_score = -math.inf
            seen = set()
            current_signature = self._design_signature(current)
            for move, raw_trial in moves:
                if time.perf_counter() >= deadline:
                    break
                trial = self._repair_first_stage_logic(raw_trial)
                if trial is None:
                    continue
                signature = self._design_signature(trial)
                if signature == current_signature or signature in seen:
                    continue
                seen.add(signature)
                score, candidate = self._network_net_score(
                    trial,
                    label=f"network_tabu_{iteration}_{len(seen)}",
                )
                if candidate is None:
                    continue
                is_tabu = tabu_until.get(move, 0) >= iteration
                aspiration = score > best_score + 1e-7
                if is_tabu and not aspiration:
                    continue
                if score > chosen_score + 1e-9:
                    chosen = candidate
                    chosen_move = move
                    chosen_score = score
            if chosen is None:
                break
            current = chosen
            current_score = chosen_score
            if chosen_move is not None:
                tabu_until[chosen_move] = iteration + tenure
            if current_score > best_score + 1e-7:
                best = current
                best_score = current_score
            signature = self._design_signature(current)
            candidate_sink[signature] = current
            ranking = self.solve_swap_ranking_estimator(
                current, label=f"network_tabu_rank_{iteration}"
            )
            score_sink[signature] = (
                current_score
                if ranking.obj_value is None
                else float(ranking.obj_value)
                - self._fixed_cost_value(current)
            )
            self.lagrangian_tabu_history.append(
                {
                    "phase": "network",
                    "iteration": iteration,
                    "current_score": current_score,
                    "best_score": best_score,
                    "selected_pairs": None,
                    "moves": str(chosen_move),
                    "time": None,
                }
            )

        best_signature = self._design_signature(best)
        candidate_sink[best_signature] = best
        best_ranking = self.solve_swap_ranking_estimator(
            best, label="network_tabu_best_rank"
        )
        score_sink[best_signature] = (
            best_score
            if best_ranking.obj_value is None
            else float(best_ranking.obj_value)
            - self._fixed_cost_value(best)
        )

    def _restricted_network_milp_refinement(
        self,
        seeds: Sequence[Mapping[str, object]],
        *,
        deadline: float,
        candidate_sink: Dict[Tuple[int, ...], Dict[str, object]],
        score_sink: Dict[Tuple[int, ...], float],
    ) -> List[Dict[str, object]]:
        """Recover compact networks by solving fixed-facility MILP neighborhoods."""
        if not seeds or time.perf_counter() >= deadline:
            return []
        recovered_networks: List[Dict[str, object]] = []
        max_seeds = max(
            0, int(getattr(config, "BENDERS_NETWORK_MILP_SEEDS", 3))
        )
        per_seed_limit = max(
            0.05,
            float(getattr(config, "BENDERS_NETWORK_MILP_TIME_LIMIT", 3.0)),
        )
        for seed_index, seed in enumerate(seeds[:max_seeds], 1):
            remaining = deadline - time.perf_counter()
            if remaining <= 0.01:
                break
            label = f"network_milp_{seed_index}"
            result = self.solve_restricted_network_milp(
                seed,
                label,
                time_limit=min(per_seed_limit, remaining),
            )
            if result.obj_value is None:
                continue
            optimized = self._estimator_snapshots.get(label, {}).get(
                "optimized_design"
            )
            if optimized is None:
                continue
            repaired = self._repair_first_stage_logic(optimized)
            if repaired is None:
                continue
            signature = self._design_signature(repaired)
            candidate_sink[signature] = repaired
            recovered_networks.append(repaired)
            ranking = self.solve_swap_ranking_estimator(
                repaired, label=f"{label}_rank"
            )
            score_sink[signature] = (
                float(result.obj_value)
                if ranking.obj_value is None
                else float(ranking.obj_value)
                - self._fixed_cost_value(repaired)
            )
            self.lagrangian_tabu_history.append(
                {
                    "phase": "network_milp",
                    "iteration": seed_index,
                    "current_score": float(result.obj_value),
                    "best_score": score_sink[signature],
                    "selected_pairs": None,
                    "moves": "joint_y_z_Gamma",
                    "time": None,
                }
            )
        recovered_networks.sort(
            key=lambda candidate: score_sink.get(
                self._design_signature(candidate), -math.inf
            ),
            reverse=True,
        )
        return recovered_networks

    def _facility_neighborhood_milp_refinement(
        self,
        seeds: Sequence[Mapping[str, object]],
        *,
        deadline: float,
        candidate_sink: Dict[Tuple[int, ...], Dict[str, object]],
        score_sink: Dict[Tuple[int, ...], float],
    ) -> List[Dict[str, object]]:
        """Expand LR facility sets within a bounded Hamming neighborhood."""
        if not seeds or time.perf_counter() >= deadline:
            return []
        max_seeds = max(
            0,
            int(
                getattr(
                    config,
                    "BENDERS_FACILITY_MILP_SEEDS",
                    1 if len(self.H) >= 30 else 2,
                )
            ),
        )
        per_seed_limit = max(
            0.05,
            float(
                getattr(
                    config,
                    "BENDERS_FACILITY_MILP_TIME_LIMIT",
                    (
                        60.0
                        if len(self.H) >= 60
                        else 40.0 if len(self.H) >= 30 else 8.0
                    ),
                )
            ),
        )
        hub_add = max(
            0,
            int(
                getattr(
                    config,
                    "BENDERS_FACILITY_HUB_ADD_LIMIT",
                    15 if len(self.H) >= 60 else 6,
                )
            ),
        )
        hub_add_minimum = max(
            0,
            int(
                getattr(
                    config,
                    "BENDERS_FACILITY_HUB_ADD_MINIMUM",
                    0,
                )
            ),
        )
        hub_drop = max(
            0,
            int(
                getattr(
                    config,
                    "BENDERS_FACILITY_HUB_DROP_LIMIT",
                    5 if len(self.H) >= 60 else 3,
                )
            ),
        )
        min_open_hubs = max(
            0,
            int(
                getattr(
                    config,
                    "BENDERS_FACILITY_MIN_OPEN_HUBS",
                    0,
                )
            ),
        )
        max_open_hubs = max(
            min_open_hubs,
            int(
                getattr(
                    config,
                    "BENDERS_FACILITY_MAX_OPEN_HUBS",
                    len(self.H),
                )
            ),
        )
        min_open_arcs = max(
            0,
            int(
                getattr(
                    config,
                    "BENDERS_FACILITY_MIN_OPEN_ARCS",
                    0,
                )
            ),
        )
        support_add = max(
            0,
            int(
                getattr(
                    config,
                    "BENDERS_FACILITY_SUPPORT_ADD_LIMIT",
                    5 if len(self.H) >= 60 else 4,
                )
            ),
        )
        support_drop = max(
            0,
            int(getattr(config, "BENDERS_FACILITY_SUPPORT_DROP_LIMIT", 5)),
        )
        max_open_bases = max(
            0,
            int(
                getattr(
                    config,
                    "BENDERS_FACILITY_MAX_OPEN_BASES",
                    len(self.L),
                )
            ),
        )
        max_open_swaps = max(
            0,
            int(
                getattr(
                    config,
                    "BENDERS_FACILITY_MAX_OPEN_SWAPS",
                    len(self.E),
                )
            ),
        )
        hub_utilization_limit = min(
            0.999,
            max(
                0.0,
                float(
                    getattr(
                        config,
                        "BENDERS_FACILITY_HUB_UTILIZATION_LIMIT",
                        0.85 if len(self.H) >= 60 else 0.92,
                    )
                ),
            ),
        )
        recovered = []
        for seed_index, seed in enumerate(seeds[:max_seeds], 1):
            remaining = deadline - time.perf_counter()
            if remaining <= 0.01:
                break
            label = f"facility_milp_{seed_index}"
            result = self.solve_lr_facility_neighborhood_milp(
                seed,
                label,
                time_limit=min(per_seed_limit, remaining),
                hub_add_minimum=hub_add_minimum,
                hub_add_limit=hub_add,
                hub_drop_limit=hub_drop,
                min_open_hubs=min_open_hubs,
                max_open_hubs=max_open_hubs,
                min_open_arcs=min_open_arcs,
                support_add_limit=support_add,
                support_drop_limit=support_drop,
                max_open_bases=max_open_bases,
                max_open_swaps=max_open_swaps,
                hub_utilization_limit=hub_utilization_limit,
            )
            if result.obj_value is None:
                continue
            optimized = self._estimator_snapshots.get(label, {}).get(
                "optimized_design"
            )
            if optimized is None:
                continue
            repaired = self._repair_first_stage_logic(optimized)
            if repaired is None:
                continue
            signature = self._design_signature(repaired)
            candidate_sink[signature] = repaired
            ranking = self.solve_swap_ranking_estimator(
                repaired, label=f"{label}_rank"
            )
            score_sink[signature] = (
                float(result.obj_value)
                if ranking.obj_value is None
                else float(ranking.obj_value)
                - self._fixed_cost_value(repaired)
            )
            recovered.append(repaired)
            self.lagrangian_tabu_history.append(
                {
                    "phase": "facility_milp",
                    "iteration": seed_index,
                    "current_score": float(result.obj_value),
                    "best_score": score_sink[signature],
                    "selected_pairs": None,
                    "moves": (
                        f"hub_add<={hub_add};hub_drop<={hub_drop};"
                        f"hub_add>={hub_add_minimum};"
                        f"hub_open={min_open_hubs}..{max_open_hubs};"
                        f"arc_open>={min_open_arcs};"
                        f"support_add<={support_add};"
                        f"support_drop<={support_drop};"
                        f"base_open<={max_open_bases};"
                        f"swap_open<={max_open_swaps};"
                        f"hub_util<={hub_utilization_limit}"
                    ),
                    "time": None,
                }
            )
        recovered.sort(
            key=lambda candidate: score_sink.get(
                self._design_signature(candidate), -math.inf
            ),
            reverse=True,
        )
        return recovered

    def generate_lagrangian_warm_starts(
        self,
        *,
        time_limit: Optional[float] = None,
    ) -> LagrangianWarmStartResult:
        """Generate starts without solving the original MISOCP or exact SOCP."""
        start = time.perf_counter()
        large_scale = len(self.H) >= 30
        very_large_scale = len(self.H) >= 60
        deadline = (
            math.inf
            if time_limit is None
            else start + max(0.0, float(time_limit))
        )
        lr_deadline = (
            math.inf
            if time_limit is None
            else start + 0.20 * max(0.0, float(time_limit))
        )
        recovery_deadline = (
            math.inf
            if time_limit is None
            else start
            + (
                0.35
                if very_large_scale
                else 0.50 if large_scale else 0.65
            )
            * max(0.0, float(time_limit))
        )
        gamma_refine_deadline = (
            math.inf
            if time_limit is None
            else start
            + (
                0.40
                if very_large_scale
                else 0.58 if large_scale else 0.83
            )
            * max(0.0, float(time_limit))
        )
        prune_deadline = (
            math.inf
            if time_limit is None
            else start
            + (
                0.42
                if very_large_scale
                else 0.60 if large_scale else 0.86
            )
            * max(0.0, float(time_limit))
        )
        tabu_deadline = (
            math.inf
            if time_limit is None
            else start
            + (
                0.45
                if very_large_scale
                else 0.62 if large_scale else 0.78
            )
            * max(0.0, float(time_limit))
        )
        network_tabu_deadline = (
            math.inf
            if time_limit is None
            else start + 0.97 * max(0.0, float(time_limit))
        )
        pairs = [
            (i, j)
            for i, j in self.A_HH
            if self._potential_od_profit(i, j) > 1e-9
        ]
        lambda_o = {pair: 0.0 for pair in pairs}
        lambda_d = {pair: 0.0 for pair in pairs}
        lambda_a = {pair: 0.0 for pair in pairs}
        best_dual = math.inf
        records: List[LagrangianRecord] = []
        candidates: Dict[Tuple[int, ...], Dict[str, object]] = {}
        candidate_estimator_scores: Dict[Tuple[int, ...], float] = {}
        last_raw: Optional[Dict[str, object]] = None
        recovery_pair_sets: List[Tuple[Pair, ...]] = []
        recovery_pair_signatures: set[Tuple[Pair, ...]] = set()
        pair_set_score_cache: Dict[Tuple[Pair, ...], float] = {}

        def register_recovered(
            recovered: Mapping[str, object],
            *,
            fast: bool = False,
        ) -> List[Dict[str, object]]:
            base_gamma = max(0.0, float(recovered["Gamma"]))
            if fast:
                gamma_factors = tuple(
                    float(value)
                    for value in getattr(
                        config,
                        "BENDERS_LR_TABU_GAMMA_FACTORS",
                        (0.55, 0.70, 0.85, 1.00),
                    )
                    if float(value) >= 0.0
                )
            else:
                gamma_factors = tuple(
                    float(value)
                    for value in getattr(
                        config,
                        "BENDERS_LR_GAMMA_FACTORS",
                        (
                            0.10,
                            0.15,
                            0.20,
                            0.25,
                            0.30,
                            0.40,
                            0.55,
                            0.70,
                            1.00,
                        ),
                    )
                    if float(value) >= 0.0
                )
            open_hubs = sum(
                1
                for hub in self.H
                if float(recovered["x"].get(hub, 0.0)) > 0.5
            )
            gamma_values = {
                float(max(0, math.ceil(base_gamma * factor)))
                for factor in gamma_factors
            }
            if not fast:
                gamma_values.update(
                    {
                        float(open_hubs),
                        float(2 * open_hubs),
                        float(4 * open_hubs),
                    }
                )
            registered = []
            for gamma in gamma_values:
                candidate = {
                    "x": dict(recovered["x"]),
                    "y": dict(recovered["y"]),
                    "z": dict(recovered["z"]),
                    "Gamma": gamma,
                }
                signature = self._design_signature(candidate)
                candidates[signature] = candidate
                registered.append(candidate)
            return registered

        def score_pair_set(pair_set: Sequence[Pair]) -> float:
            if not pair_set or last_raw is None:
                return 0.0
            canonical = tuple(sorted(set(pair_set)))
            if canonical in pair_set_score_cache:
                return pair_set_score_cache[canonical]
            best_score = -math.inf
            best_candidate = None
            best_snapshot = None
            recovery_modes = (
                (True, True),
                (True, False),
                (False, True),
            )
            for mode_index, (consolidate, prefer_swap) in enumerate(
                recovery_modes, 1
            ):
                recovered = self._recover_lr_design(
                    last_raw,
                    list(canonical),
                    pair_limit=len(canonical),
                    consolidate_network=consolidate,
                    prefer_swap_routes=prefer_swap,
                )
                if time.perf_counter() >= tabu_deadline:
                    break
                label = (
                    f"lr_subset_net_{len(pair_set_score_cache) + 1}_"
                    f"{mode_index}"
                )
                score, candidate = self._network_net_score(
                    recovered, label=label
                )
                if candidate is None:
                    continue
                signature = self._design_signature(candidate)
                candidates[signature] = candidate
                if score > best_score + 1e-9:
                    best_score = score
                    best_candidate = candidate
                    best_snapshot = self._estimator_snapshots.get(label)

            if (
                best_candidate is not None
                and time.perf_counter() < tabu_deadline
            ):
                best_signature = self._design_signature(best_candidate)
                ranking = self.solve_swap_ranking_estimator(
                    best_candidate,
                    label=f"lr_subset_rank_{len(pair_set_score_cache) + 1}",
                )
                candidate_estimator_scores[best_signature] = (
                    best_score
                    if ranking.obj_value is None
                    else float(ranking.obj_value)
                    - self._fixed_cost_value(best_candidate)
                )
                if best_snapshot is not None:
                    projected = self._prune_design_from_estimator(
                        best_candidate, best_snapshot
                    )
                    projected_score, projected_candidate = (
                        self._network_net_score(
                            projected,
                            label=(
                                f"lr_subset_projected_net_"
                                f"{len(pair_set_score_cache) + 1}"
                            ),
                        )
                    )
                    if projected_candidate is not None:
                        projected_signature = self._design_signature(
                            projected_candidate
                        )
                        candidates[projected_signature] = projected_candidate
                        projected_ranking = self.solve_swap_ranking_estimator(
                            projected_candidate,
                            label=(
                                f"lr_subset_projected_rank_"
                                f"{len(pair_set_score_cache) + 1}"
                            ),
                        )
                        candidate_estimator_scores[projected_signature] = (
                            projected_score
                            if projected_ranking.obj_value is None
                            else float(projected_ranking.obj_value)
                            - self._fixed_cost_value(projected_candidate)
                        )
                        best_score = max(best_score, projected_score)
            pair_set_score_cache[canonical] = best_score
            return best_score

        for it in range(1, self.lr_iterations + 1):
            if time.perf_counter() >= lr_deadline:
                break
            selected = {
                pair: int(
                    self._potential_od_profit(*pair)
                    - lambda_o[pair]
                    - lambda_d[pair]
                    - lambda_a[pair]
                    > 0.0
                )
                for pair in pairs
            }
            service_value = sum(
                max(
                    0.0,
                    self._potential_od_profit(*pair)
                    - lambda_o[pair]
                    - lambda_d[pair]
                    - lambda_a[pair],
                )
                for pair in pairs
            )

            design_model, variables = self._build_lr_design_subproblem(
                lambda_o, lambda_d, lambda_a
            )
            design_model.Params.TimeLimit = max(
                0.01, min(10.0, lr_deadline - time.perf_counter())
            )
            design_model.optimize()
            if design_model.SolCount == 0:
                break

            raw = {
                "x": {u: float(variables["x"][u].X) for u in self.N_x},
                "y": {arc: float(variables["y"][arc].X) for arc in self.AY},
                "z": {
                    (i, c): float(variables["z"][i, c].X)
                    for i in self.H
                    for c in range(len(config.MU_HUB))
                },
            }
            last_raw = raw
            dual_bound = float(service_value + design_model.ObjVal)
            best_dual = min(best_dual, dual_bound)
            active_pairs = [pair for pair, value in selected.items() if value]
            recovery_limits = tuple(
                int(value)
                for value in getattr(
                    config,
                    "BENDERS_LR_RECOVERY_PAIR_LIMITS",
                    (
                        1,
                        3,
                        5,
                        10,
                        20,
                        30,
                        40,
                        50,
                    ),
                )
                if 0 < int(value) <= max(50, 3 * len(self.H))
            )
            for pair_limit in recovery_limits:
                pair_set = tuple(
                    sorted(
                        active_pairs,
                        key=lambda pair: self._potential_od_profit(*pair),
                        reverse=True,
                    )[:pair_limit]
                )
                if pair_set and pair_set not in recovery_pair_signatures:
                    recovery_pair_signatures.add(pair_set)
                    recovery_pair_sets.append(pair_set)

            violations = []
            for i, j in pairs:
                q = float(selected[i, j])
                violations.extend(
                    (
                        q - float(raw["x"][i]),
                        q - float(raw["x"][j]),
                        q - float(raw["y"].get((i, j), 0.0)),
                    )
                )
            norm_sq = sum(value * value for value in violations)
            step = self.lr_initial_step / math.sqrt(float(it))
            if norm_sq <= 1e-12:
                step = 0.0

            for i, j in pairs:
                q = float(selected[i, j])
                lambda_o[i, j] = max(
                    0.0, lambda_o[i, j] + step * (q - float(raw["x"][i]))
                )
                lambda_d[i, j] = max(
                    0.0, lambda_d[i, j] + step * (q - float(raw["x"][j]))
                )
                lambda_a[i, j] = max(
                    0.0,
                    lambda_a[i, j]
                    + step * (q - float(raw["y"].get((i, j), 0.0))),
                )

            records.append(
                LagrangianRecord(
                    iteration=it,
                    dual_bound=dual_bound,
                    best_dual_bound=best_dual,
                    selected_pairs=sum(selected.values()),
                    open_hubs=sum(
                        1 for h in self.H if float(raw["x"][h]) > 0.5
                    ),
                    violation_norm=math.sqrt(norm_sq),
                    step_size=step,
                )
            )

        if last_raw is not None:
            for pair_set in recovery_pair_sets:
                if time.perf_counter() >= recovery_deadline:
                    break
                register_recovered(
                    self._recover_lr_design(
                        last_raw,
                        list(pair_set),
                        pair_limit=len(pair_set),
                    )
                )
                register_recovered(
                    self._recover_lr_design(
                        last_raw,
                        list(pair_set),
                        pair_limit=len(pair_set),
                        prefer_swap_routes=False,
                    )
                )
                register_recovered(
                    self._recover_lr_design(
                        last_raw,
                        list(pair_set),
                        pair_limit=len(pair_set),
                        consolidate_network=False,
                    )
                )

        # Prefix-only recovery systematically misses compact designs when the
        # highest-demand OD pair is expensive to close into a circulation.
        # Explore LR-ranked singleton and two-pair neighborhoods without using
        # the exact SOCP; candidates are still ranked by the estimator LP.
        if last_raw is not None and pairs:
            pair_pool_size = int(
                getattr(
                    config,
                    "BENDERS_LR_PAIR_POOL",
                    min(len(pairs), max(40, 4 * len(self.H))),
                )
            )
            reduced_ranked_pairs = sorted(
                pairs,
                key=lambda pair: (
                    self._potential_od_profit(*pair)
                    - lambda_o[pair]
                    - lambda_d[pair]
                    - lambda_a[pair]
                ),
                reverse=True,
            )[:pair_pool_size]
            profit_ranked_pairs = sorted(
                pairs,
                key=lambda pair: self._potential_od_profit(*pair),
                reverse=True,
            )[:pair_pool_size]
            undirected_groups: Dict[Tuple[Node, Node], List[Pair]] = {}
            for pair in pairs:
                key = tuple(sorted(pair))
                undirected_groups.setdefault(key, []).append(pair)
            ranked_undirected = sorted(
                undirected_groups.items(),
                key=lambda item: sum(
                    self._potential_od_profit(*pair)
                    for pair in item[1]
                ),
                reverse=True,
            )
            cycle_ranked_pairs = []
            for _, directions in ranked_undirected:
                cycle_ranked_pairs.extend(
                    sorted(
                        directions,
                        key=lambda pair: self._potential_od_profit(*pair),
                        reverse=True,
                    )
                )
                if len(cycle_ranked_pairs) >= pair_pool_size:
                    break
            cycle_ranked_pairs = cycle_ranked_pairs[:pair_pool_size]
            ranked_lr_pairs = list(
                dict.fromkeys(
                    [
                        *cycle_ranked_pairs,
                        *profit_ranked_pairs,
                        *reduced_ranked_pairs,
                    ]
                )
            )
            singleton_limit = (
                len(ranked_lr_pairs)
                if len(self.H) <= 10
                else min(10, len(ranked_lr_pairs))
            )
            for pair in ranked_lr_pairs[:singleton_limit]:
                if time.perf_counter() >= recovery_deadline:
                    break
                register_recovered(
                    self._recover_lr_design(
                        last_raw, [pair], pair_limit=1
                    )
                )
            if ranked_lr_pairs:
                anchor = ranked_lr_pairs[0]
                pair_extension_limit = (
                    len(ranked_lr_pairs) - 1
                    if len(self.H) <= 10
                    else min(10, len(ranked_lr_pairs) - 1)
                )
                for pair in ranked_lr_pairs[1 : 1 + pair_extension_limit]:
                    if time.perf_counter() >= recovery_deadline:
                        break
                    register_recovered(
                        self._recover_lr_design(
                            last_raw, [anchor, pair], pair_limit=2
                        )
                    )
                current_pairs = list(
                    cycle_ranked_pairs[
                        : min(
                            len(cycle_ranked_pairs),
                            int(
                                getattr(
                                    config,
                                    "BENDERS_LR_BACKWARD_START_PAIRS",
                                    min(
                                        len(profit_ranked_pairs),
                                        max(25, int(2.5 * len(self.H))),
                                    ),
                                )
                            ),
                        )
                    ]
                )
                current_score = score_pair_set(current_pairs)
                max_backward = int(
                    getattr(config, "BENDERS_LR_BACKWARD_ITERATIONS", 2)
                )
                for _ in range(max_backward):
                    if (
                        len(current_pairs) <= 1
                        or time.perf_counter() >= recovery_deadline
                    ):
                        break
                    best_trial = None
                    best_trial_score = -math.inf
                    for pair in current_pairs:
                        if time.perf_counter() >= recovery_deadline:
                            break
                        trial = [item for item in current_pairs if item != pair]
                        score = score_pair_set(trial)
                        if score > best_trial_score:
                            best_trial_score = score
                            best_trial = trial
                    if best_trial is None:
                        break
                    current_pairs = best_trial
                    current_score = best_trial_score

                # LR-guided Tabu search on OD-cycle subsets.  The neighborhood
                # is evaluated exclusively by the strengthened swap-aware LP
                # estimator; exact SOCP recourse is not called here.
                tabu_iterations = int(
                    getattr(config, "BENDERS_LR_TABU_ITERATIONS", 25)
                )
                tabu_tenure = max(
                    1, int(getattr(config, "BENDERS_LR_TABU_TENURE", 5))
                )
                add_width = max(
                    1,
                    int(getattr(config, "BENDERS_LR_TABU_ADD_WIDTH", 6)),
                )
                drop_width = max(
                    1,
                    int(getattr(config, "BENDERS_LR_TABU_DROP_WIDTH", 5)),
                )
                swap_in_width = max(
                    1,
                    int(
                        getattr(
                            config, "BENDERS_LR_TABU_SWAP_IN_WIDTH", 4
                        )
                    ),
                )
                swap_out_width = max(
                    1,
                    int(
                        getattr(
                            config, "BENDERS_LR_TABU_SWAP_OUT_WIDTH", 3
                        )
                    ),
                )

                lr_pair_score = {
                    pair: (
                        self._potential_od_profit(*pair)
                        - lambda_o[pair]
                        - lambda_d[pair]
                        - lambda_a[pair]
                    )
                    for pair in ranked_lr_pairs
                }
                seed_states = [
                    tuple(
                        sorted(
                            profit_ranked_pairs[
                                : min(size, len(profit_ranked_pairs))
                            ]
                        )
                    )
                    for size in (10, 20, 30, 40, 50)
                    if profit_ranked_pairs
                ]
                seed_states.extend(
                    tuple(
                        sorted(
                            reduced_ranked_pairs[
                                : min(size, len(reduced_ranked_pairs))
                            ]
                        )
                    )
                    for size in (20, 40)
                    if reduced_ranked_pairs
                )
                seed_states.extend(
                    tuple(
                        sorted(
                            cycle_ranked_pairs[
                                : min(size, len(cycle_ranked_pairs))
                            ]
                        )
                    )
                    for size in (10, 20, 30, 40, 50)
                    if cycle_ranked_pairs
                )
                seed_states.append(tuple(sorted(current_pairs)))
                seed_states = list(dict.fromkeys(seed_states))
                current_state = max(
                    seed_states,
                    key=lambda state: score_pair_set(state),
                )
                current_score = score_pair_set(current_state)
                best_state = current_state
                best_tabu_score = current_score
                tabu_until: Dict[Tuple[str, Pair], int] = {}

                for tabu_iteration in range(1, tabu_iterations + 1):
                    if time.perf_counter() >= tabu_deadline:
                        break
                    current_set = set(current_state)
                    closed = [
                        pair
                        for pair in ranked_lr_pairs
                        if pair not in current_set
                    ][:add_width]
                    open_for_drop = sorted(
                        current_set,
                        key=lambda pair: lr_pair_score.get(pair, -math.inf),
                    )[:drop_width]
                    neighbors: List[
                        Tuple[Tuple[Pair, ...], Tuple[Tuple[str, Pair], ...]]
                    ] = []
                    for pair in closed:
                        neighbors.append(
                            (
                                tuple(sorted(current_set | {pair})),
                                (("add", pair),),
                            )
                        )
                    if len(current_set) > 1:
                        for pair in open_for_drop:
                            neighbors.append(
                                (
                                    tuple(sorted(current_set - {pair})),
                                    (("drop", pair),),
                                )
                            )
                    for pair_out in open_for_drop[:swap_out_width]:
                        for pair_in in closed[:swap_in_width]:
                            neighbors.append(
                                (
                                    tuple(
                                        sorted(
                                            (current_set - {pair_out})
                                            | {pair_in}
                                        )
                                    ),
                                    (
                                        ("drop", pair_out),
                                        ("add", pair_in),
                                    ),
                                )
                            )

                    chosen_state = None
                    chosen_moves = None
                    chosen_score = -math.inf
                    seen_states = set()
                    for state, moves in neighbors:
                        if state in seen_states or not state:
                            continue
                        seen_states.add(state)
                        if time.perf_counter() >= tabu_deadline:
                            break
                        score = score_pair_set(state)
                        is_tabu = any(
                            tabu_until.get(move, 0) >= tabu_iteration
                            for move in moves
                        )
                        aspiration = score > best_tabu_score + 1e-7
                        if is_tabu and not aspiration:
                            continue
                        if score > chosen_score + 1e-9:
                            chosen_state = state
                            chosen_moves = moves
                            chosen_score = score
                    if chosen_state is None:
                        break

                    current_state = chosen_state
                    current_score = chosen_score
                    for move in chosen_moves or ():
                        reverse = (
                            ("drop", move[1])
                            if move[0] == "add"
                            else ("add", move[1])
                        )
                        tabu_until[reverse] = tabu_iteration + tabu_tenure
                    if current_score > best_tabu_score + 1e-7:
                        best_tabu_score = current_score
                        best_state = current_state
                    self.lagrangian_tabu_history.append(
                        {
                            "iteration": tabu_iteration,
                            "current_score": current_score,
                            "best_score": best_tabu_score,
                            "selected_pairs": len(current_state),
                            "moves": ";".join(
                                f"{kind}:{pair[0]}->{pair[1]}"
                                for kind, pair in (chosen_moves or ())
                            ),
                            "time": time.perf_counter() - start,
                        }
                    )

                # Ensure the best Tabu state is registered even if the last
                # move was non-improving.
                score_pair_set(best_state)

        # Refine fleet size around the best estimator-ranked networks.  The
        # queue approximation is an upper-bound surrogate, so several nearby
        # Gamma values are deliberately retained for exact Benders
        # certification instead of trusting a single surrogate optimum.
        gamma_refine_sources = sorted(
            list(candidates.values()),
            key=lambda candidate: candidate_estimator_scores.get(
                self._design_signature(candidate), -math.inf
            ),
            reverse=True,
        )[
            : int(
                getattr(config, "BENDERS_LR_GAMMA_REFINE_NETWORKS", 8)
            )
        ]
        gamma_radius = max(
            0, int(getattr(config, "BENDERS_LR_GAMMA_REFINE_RADIUS", 20))
        )
        gamma_step = max(
            1, int(getattr(config, "BENDERS_LR_GAMMA_REFINE_STEP", 2))
        )
        for source_index, source in enumerate(gamma_refine_sources, 1):
            if time.perf_counter() >= gamma_refine_deadline:
                break
            center = int(round(float(source["Gamma"])))
            for gamma in range(
                max(0, center - gamma_radius),
                center + gamma_radius + 1,
                gamma_step,
            ):
                if time.perf_counter() >= gamma_refine_deadline:
                    break
                candidate = {
                    "x": dict(source["x"]),
                    "y": dict(source["y"]),
                    "z": dict(source["z"]),
                    "Gamma": float(gamma),
                }
                signature = self._design_signature(candidate)
                candidates[signature] = candidate
                if signature in candidate_estimator_scores:
                    continue
                estimate = self.solve_swap_ranking_estimator(
                    candidate,
                    label=f"lr_gamma_refine_{source_index}_{gamma}",
                )
                candidate_estimator_scores[signature] = (
                    -math.inf
                    if estimate.obj_value is None
                    else float(estimate.obj_value)
                    - self._fixed_cost_value(candidate)
                )

        # LP-support projection is a stronger pruning move than deleting one
        # physical arc at a time: every facility and arc unused by the
        # swap-aware maximum-profit flow is removed simultaneously.  The
        # projected design is then evaluated by the same LP estimator only.
        prune_limit = int(
            getattr(config, "BENDERS_LR_PRUNE_CANDIDATES", 30)
        )
        prune_sources = sorted(
            list(candidates.values()),
            key=lambda candidate: candidate_estimator_scores.get(
                self._design_signature(candidate), -math.inf
            ),
            reverse=True,
        )[:prune_limit]
        for prune_index, candidate in enumerate(prune_sources, 1):
            if time.perf_counter() >= prune_deadline:
                break
            label = f"lr_prune_source_{prune_index}"
            estimate = self.solve_swap_ranking_estimator(
                candidate, label=label
            )
            if estimate.obj_value is None:
                continue
            signature = self._design_signature(candidate)
            candidate_estimator_scores[signature] = (
                float(estimate.obj_value) - self._fixed_cost_value(candidate)
            )
            snapshot = self._estimator_snapshots.get(label)
            if snapshot is None:
                continue
            pruned = self._prune_design_from_estimator(candidate, snapshot)
            for projected in register_recovered(pruned):
                if time.perf_counter() >= prune_deadline:
                    break
                projected_signature = self._design_signature(projected)
                projected_label = (
                    f"lr_prune_projected_{prune_index}_"
                    f"{int(round(float(projected['Gamma'])))}"
                )
                projected_estimate = self.solve_swap_ranking_estimator(
                    projected, label=projected_label
                )
                candidate_estimator_scores[projected_signature] = (
                    -math.inf
                    if projected_estimate.obj_value is None
                    else float(projected_estimate.obj_value)
                    - self._fixed_cost_value(projected)
                )

        network_seed_limit = int(
            getattr(config, "BENDERS_NETWORK_TABU_SEEDS", 5)
        )
        network_seeds = sorted(
            list(candidates.values()),
            key=lambda candidate: candidate_estimator_scores.get(
                self._design_signature(candidate), -math.inf
            ),
            reverse=True,
        )[:network_seed_limit]
        network_milp_designs = []
        facility_milp_designs = []
        if self.use_restricted_network_milp:
            network_milp_designs = self._restricted_network_milp_refinement(
                network_seeds,
                deadline=network_tabu_deadline,
                candidate_sink=candidates,
                score_sink=candidate_estimator_scores,
            )
            if len(self.H) >= 30:
                facility_seeds = [
                    *network_milp_designs,
                    *network_seeds,
                ]
                facility_milp_designs = (
                    self._facility_neighborhood_milp_refinement(
                        facility_seeds,
                        deadline=network_tabu_deadline,
                        candidate_sink=candidates,
                        score_sink=candidate_estimator_scores,
                    )
                )
        network_seeds = sorted(
            list(candidates.values()),
            key=lambda candidate: candidate_estimator_scores.get(
                self._design_signature(candidate), -math.inf
            ),
            reverse=True,
        )[:network_seed_limit]
        self._network_tabu_refinement(
            network_seeds,
            deadline=network_tabu_deadline,
            candidate_sink=candidates,
            score_sink=candidate_estimator_scores,
        )

        # Network Tabu can create a materially better topology after the first
        # Gamma-refinement phase.  Re-expand fleet sizes around those new
        # networks so exact initial-design evaluation is not tied to the LP
        # estimator's rounded fleet optimum.
        post_network_sources = sorted(
            list(candidates.values()),
            key=lambda candidate: candidate_estimator_scores.get(
                self._design_signature(candidate), -math.inf
            ),
            reverse=True,
        )[
            : int(
                getattr(
                    config, "BENDERS_NETWORK_POST_GAMMA_NETWORKS", 5
                )
            )
        ]
        post_gamma_radius = max(
            0,
            int(
                getattr(
                    config, "BENDERS_NETWORK_POST_GAMMA_RADIUS", 8
                )
            ),
        )
        for source_index, source in enumerate(post_network_sources, 1):
            if time.perf_counter() >= deadline:
                break
            center = int(round(float(source["Gamma"])))
            for gamma in range(
                max(0, center - post_gamma_radius),
                center + post_gamma_radius + 1,
            ):
                if time.perf_counter() >= deadline:
                    break
                candidate = {
                    "x": dict(source["x"]),
                    "y": dict(source["y"]),
                    "z": dict(source["z"]),
                    "Gamma": float(gamma),
                }
                signature = self._design_signature(candidate)
                candidates[signature] = candidate
                if signature in candidate_estimator_scores:
                    continue
                estimate = self.solve_swap_ranking_estimator(
                    candidate,
                    label=f"network_post_gamma_{source_index}_{gamma}",
                )
                candidate_estimator_scores[signature] = (
                    -math.inf
                    if estimate.obj_value is None
                    else float(estimate.obj_value)
                    - self._fixed_cost_value(candidate)
                )

        empty = {
            "x": {u: 0.0 for u in self.N_x},
            "y": {arc: 0.0 for arc in self.AY},
            "z": {
                (i, c): 0.0
                for i in self.H
                for c in range(len(config.MU_HUB))
            },
            "Gamma": 0.0,
        }
        empty_signature = self._design_signature(empty)
        candidates[empty_signature] = empty

        scored = [(0.0, empty)]
        for idx, design in enumerate(candidates.values(), 1):
            if self._design_signature(design) == empty_signature:
                continue
            signature = self._design_signature(design)
            score = candidate_estimator_scores.get(signature, -math.inf)
            if not math.isfinite(score):
                if time.perf_counter() >= deadline:
                    continue
                estimate = self.solve_swap_ranking_estimator(
                    design, label=f"lr_rank_{idx}"
                )
                score = -math.inf
                if estimate.obj_value is not None:
                    score = float(estimate.obj_value) - self._fixed_cost_value(design)
            scored.append((score, design))
        scored.sort(key=lambda item: item[0], reverse=True)
        designs = []
        selected_signatures = set()

        # Preserve the rounded restricted-MILP fleet size and its immediate
        # upper neighbor for exact SOCP evaluation.  LP queue tangents tend to
        # underestimate the fleet size by roughly one unit, while a pure
        # global LP-score truncation can discard that neighboring candidate.
        priority_networks = max(
            0, int(getattr(config, "BENDERS_NETWORK_MILP_PRIORITY_SEEDS", 1))
        )
        priority_designs = sorted(
            [*facility_milp_designs, *network_milp_designs],
            key=lambda candidate: candidate_estimator_scores.get(
                self._design_signature(candidate), -math.inf
            ),
            reverse=True,
        )
        for network in priority_designs[:priority_networks]:
            center = int(round(float(network["Gamma"])))
            if len(self.H) >= 60:
                priority_gamma_values = [
                    center,
                    int(math.ceil(1.25 * center)),
                    int(math.ceil(1.50 * center)),
                    int(math.ceil(1.75 * center)),
                    int(math.ceil(2.00 * center)),
                ]
            elif len(self.H) >= 30:
                priority_gamma_values = [
                    center,
                    center - 2,
                    center - 4,
                    center - 6,
                    center + 1,
                ]
            else:
                priority_gamma_values = [
                    center,
                    center + 1,
                    center - 1,
                    center + 2,
                ]
            for gamma in priority_gamma_values:
                candidate = {
                    "x": dict(network["x"]),
                    "y": dict(network["y"]),
                    "z": dict(network["z"]),
                    "Gamma": float(max(0, gamma)),
                }
                signature = self._design_signature(candidate)
                if signature in selected_signatures:
                    continue
                designs.append(candidate)
                selected_signatures.add(signature)
                if len(designs) >= self.lr_max_designs:
                    break
            if len(designs) >= self.lr_max_designs:
                break

        for _, design in scored:
            if len(designs) >= self.lr_max_designs:
                break
            signature = self._design_signature(design)
            if signature in selected_signatures:
                continue
            designs.append(design)
            selected_signatures.add(signature)
        result = LagrangianWarmStartResult(
            designs=designs,
            best_dual_bound=best_dual,
            history=[
                {
                    "iteration": float(record.iteration),
                    "dual_bound": record.dual_bound,
                    "best_dual_bound": record.best_dual_bound,
                    "selected_pairs": float(record.selected_pairs),
                    "open_hubs": float(record.open_hubs),
                    "violation_norm": record.violation_norm,
                    "step_size": record.step_size,
                }
                for record in records
            ],
            wall_time=time.perf_counter() - start,
            tabu_history=list(self.lagrangian_tabu_history),
        )
        self.lagrangian_result = result
        return result

    def _evaluate_master_pool(
        self,
        *,
        iteration: int,
        lower_bound: float,
        deadline: float,
    ) -> Tuple[float, int]:
        """Evaluate a small estimator-ranked subset of the MILP solution pool."""
        if (
            self.pool_exact_evaluations_per_iteration <= 0
            or self.master is None
            or int(self.master.SolCount) <= 1
        ):
            return lower_bound, 0

        candidates = []
        max_pool = min(int(self.master.SolCount), self.pool_solutions)
        for solution_number in range(1, max_pool):
            if time.perf_counter() >= deadline:
                break
            try:
                design = self._extract_master_design(
                    solution_number=solution_number
                )
            except (gp.GurobiError, AttributeError):
                continue
            signature = self._design_signature(design)
            if signature in self._pool_exact_signatures:
                continue
            estimate = self.solve_swap_ranking_estimator(
                design,
                label=f"pool_est_{iteration}_{solution_number}",
            )
            score = -math.inf
            if estimate.obj_value is not None:
                score = float(estimate.obj_value) - self._fixed_cost_value(
                    design
                )
            candidates.append((score, signature, design))

        self.master.Params.SolutionNumber = 0
        candidates.sort(key=lambda item: item[0], reverse=True)
        cuts_added = 0
        for _, signature, design in candidates[
            : self.pool_exact_evaluations_per_iteration
        ]:
            if time.perf_counter() >= deadline:
                break
            self._pool_exact_signatures.add(signature)
            exact = self.solve_subproblem(
                design,
                label=f"pool_exact_{iteration}_{cuts_added + 1}",
            )
            if exact.obj_value is None:
                continue
            total_obj = float(exact.obj_value) - self._fixed_cost_value(design)
            if total_obj > lower_bound + 1e-7:
                lower_bound = total_obj
                self.best_total_obj = total_obj
                self.best_operational_obj = float(exact.obj_value)
                self.best_design = design
            if exact.cut_expr_data is not None and exact.rhs_at_reference is not None:
                self._add_benders_cut(exact, "pool_exact_benders")
                cuts_added += 1
        return lower_bound, cuts_added

    def _process_initial_designs_with_deadline(
        self,
        lower_bound: float,
        *,
        deadline: float,
    ) -> Tuple[float, int]:
        """Evaluate LR starts without exceeding the shared search budget."""
        if self._initial_designs_processed or not self.initial_designs:
            return lower_bound, 0

        added = 0
        best_initial = None
        best_initial_obj = -GRB.INFINITY
        for idx, design in enumerate(self.initial_designs, 1):
            remaining = deadline - time.perf_counter()
            if remaining <= 0.01:
                break
            had_limit = hasattr(config, "BENDERS_SUB_TIME_LIMIT")
            old_limit = getattr(config, "BENDERS_SUB_TIME_LIMIT", None)
            configured_limit = (
                remaining
                if old_limit is None
                else min(float(old_limit), remaining)
            )
            setattr(config, "BENDERS_SUB_TIME_LIMIT", configured_limit)
            try:
                sub = self.solve_subproblem(
                    design, label=f"initial{idx}"
                )
            finally:
                if had_limit:
                    setattr(config, "BENDERS_SUB_TIME_LIMIT", old_limit)
                else:
                    delattr(config, "BENDERS_SUB_TIME_LIMIT")
            if sub.obj_value is None:
                self.initial_design_history.append(
                    {
                        "index": idx,
                        "source": "lagrangian",
                        "status": int(sub.status),
                        "sub_obj": None,
                        "fixed_cost": self._fixed_cost_value(design),
                        "total_obj": None,
                        "Gamma": float(design.get("Gamma", 0.0)),
                    }
                )
                continue

            total_obj = float(sub.obj_value) - self._fixed_cost_value(design)
            self.initial_design_history.append(
                {
                    "index": idx,
                    "source": "lagrangian",
                    "status": int(sub.status),
                    "sub_obj": float(sub.obj_value),
                    "fixed_cost": self._fixed_cost_value(design),
                    "total_obj": total_obj,
                    "Gamma": float(design.get("Gamma", 0.0)),
                }
            )
            if total_obj > lower_bound + 1e-7:
                lower_bound = total_obj
                self.best_total_obj = total_obj
                self.best_operational_obj = float(sub.obj_value)
                self.best_design = design
            if total_obj > best_initial_obj + 1e-7:
                best_initial_obj = total_obj
                best_initial = design
            if sub.cut_expr_data is not None and sub.rhs_at_reference is not None:
                self._add_benders_cut(sub, "initial")
                added += 1

        if best_initial is not None:
            self._apply_master_start(best_initial)
            self._initialize_or_update_core(best_initial)
        self._initial_designs_processed = True
        if added:
            print(
                f"Loaded {added} initial Benders cut(s); "
                f"initial LB={lower_bound:.4f}."
            )
        return lower_bound, added

    # ------------------------------------------------------------------
    # Main exact/upper-bound-driven loop
    # ------------------------------------------------------------------

    def solve(
        self,
        max_iterations: Optional[int] = None,
        tolerance: Optional[float] = None,
        time_limit: Optional[float] = None,
        lr_time_limit: Optional[float] = None,
    ) -> bool:
        self.build_master()
        assert self.master is not None
        self.apply_master_solver_config()
        max_iterations = int(
            max_iterations
            if max_iterations is not None
            else getattr(config, "BENDERS_MAX_ITER", 100)
        )
        tolerance = float(
            tolerance
            if tolerance is not None
            else getattr(config, "BENDERS_TOL", 1e-4)
        )
        time_limit = float(
            time_limit
            if time_limit is not None
            else getattr(
                config,
                "BENDERS_TIME_LIMIT",
                getattr(config, "MODEL_TIME_LIMIT", 900.0),
            )
        )
        t0 = time.perf_counter()
        lr_global_bound = math.inf
        global_seed: Optional[Dict[str, object]] = None

        if not self._lr_generated and self.use_lagrangian_warmstart:
            lr_budget = (
                min(0.20 * time_limit, 120.0)
                if lr_time_limit is None
                else min(float(lr_time_limit), time_limit)
            )
            lr_result = self.generate_lagrangian_warm_starts(
                time_limit=lr_budget
            )
            for design in lr_result.designs:
                self.add_initial_design(design)
            if lr_result.designs:
                global_seed = lr_result.designs[0]
            lr_global_bound = float(lr_result.best_dual_bound)
            self._lr_generated = True
        elif not self._lr_generated:
            empty = {
                "x": {u: 0.0 for u in self.N_x},
                "y": {arc: 0.0 for arc in self.AY},
                "z": {
                    (i, c): 0.0
                    for i in self.H
                    for c in range(len(config.MU_HUB))
                },
                "Gamma": 0.0,
            }
            self.add_initial_design(empty)
            global_seed = empty
            self._lr_generated = True

        if (
            self.use_global_network_upper_bound
            and global_seed is not None
            and time.perf_counter() < t0 + time_limit
        ):
            remaining = t0 + time_limit - time.perf_counter()
            fraction = max(
                0.0,
                float(
                    getattr(
                        config, "BENDERS_GLOBAL_UB_TIME_FRACTION", 0.10
                    )
                ),
            )
            max_budget = max(
                0.0,
                float(
                    getattr(config, "BENDERS_GLOBAL_UB_TIME_LIMIT", 60.0)
                ),
            )
            global_budget = min(max_budget, fraction * time_limit, remaining)
            if global_budget >= 0.05:
                global_start = time.perf_counter()
                global_result = self.solve_global_network_upper_bound(
                    global_seed,
                    "global_network_upper_bound",
                    time_limit=global_budget,
                )
                self.global_network_wall_time = (
                    time.perf_counter() - global_start
                )
                self.global_network_status = int(global_result.status)
                if global_result.obj_value is not None:
                    self.global_network_bound = float(
                        global_result.obj_value
                    )
                    snapshot = self._estimator_snapshots.get(
                        "global_network_upper_bound", {}
                    )
                    incumbent = snapshot.get("global_milp_incumbent")
                    gap = snapshot.get("global_milp_gap")
                    self.global_network_incumbent = (
                        None if incumbent is None else float(incumbent)
                    )
                    self.global_network_gap = (
                        None if gap is None else float(gap)
                    )
                    safety = 1e-6 * max(
                        1.0, abs(self.global_network_bound)
                    )
                    self.master.addConstr(
                        self.master.getObjective()
                        <= self.global_network_bound + safety,
                        name="global_network_relaxation_ub",
                    )

        lower_bound = -GRB.INFINITY
        upper_bound = min(
            lr_global_bound,
            (
                math.inf
                if self.global_network_bound is None
                else self.global_network_bound
            ),
        )
        lower_bound, initial_cuts = self._process_initial_designs_with_deadline(
            lower_bound,
            deadline=t0 + time_limit,
        )
        consecutive_screens = 0

        for iteration in range(1, max_iterations + 1):
            elapsed = time.perf_counter() - t0
            if elapsed >= time_limit:
                break
            self.master.Params.TimeLimit = max(1.0, time_limit - elapsed)
            self.master.optimize()
            if (
                self.master.Status
                not in {GRB.OPTIMAL, GRB.TIME_LIMIT, GRB.SUBOPTIMAL}
                or self.master.SolCount == 0
            ):
                break

            master_bound = float(self.master.ObjBound)
            if math.isfinite(master_bound):
                if lower_bound > -0.5 * float(GRB.INFINITY):
                    master_bound = max(master_bound, lower_bound)
                upper_bound = min(upper_bound, master_bound)
            design = self._extract_master_design()
            eta_value = float(self.master_vars["eta"].X)
            fixed_cost = self._fixed_cost_value(design)

            topology_cuts = (
                self.add_topology_connectivity_cuts(design)
                if self.use_topology_cuts
                else 0
            )
            swap_cuts = (
                self.add_swap_reachability_cuts(design)
                if self.use_swap_reachability_cuts
                else 0
            )

            estimator_bounds: List[float] = []
            topology_estimate = None
            swap_estimate = None
            topology_service_estimate = None
            swap_service_estimate = None
            network_net_estimate = None
            topology_core_estimate = None
            swap_core_estimate = None
            if self.use_topology_estimator:
                topology_estimate = self.solve_topology_profit_estimator(
                    design, label=f"topology_{iteration}"
                )
                if (
                    topology_estimate.obj_value is not None
                    and topology_estimate.cut_expr_data is not None
                ):
                    estimator_bounds.append(float(topology_estimate.obj_value))
                    self._add_benders_cut(
                        topology_estimate, "topology_estimator"
                    )
                    self.flow_cut_stats.topology_estimator_cuts += 1

            if self.use_swap_estimator:
                swap_estimate = self.solve_swap_profit_estimator(
                    design, label=f"swap_{iteration}"
                )
                if (
                    swap_estimate.obj_value is not None
                    and swap_estimate.cut_expr_data is not None
                ):
                    estimator_bounds.append(float(swap_estimate.obj_value))
                    self._add_benders_cut(swap_estimate, "swap_estimator")
                    self.flow_cut_stats.swap_estimator_cuts += 1
                network_net_estimate = self.solve_swap_network_net_estimator(
                    design, label=f"network_net_{iteration}"
                )
                if network_net_estimate.obj_value is not None:
                    self.add_network_net_profit_cut(
                        design,
                        float(network_net_estimate.obj_value),
                    )

            if self.use_topology_estimator:
                topology_service_estimate = (
                    self.solve_topology_max_service_estimator(
                        design, label=f"topology_service_{iteration}"
                    )
                )
                scaled = self._service_result_as_profit_cut(
                    topology_service_estimate
                )
                if (
                    scaled.obj_value is not None
                    and scaled.cut_expr_data is not None
                ):
                    self._add_benders_cut(
                        scaled, "topology_max_service"
                    )
                    self.flow_cut_stats.topology_max_service_cuts += 1
            if self.use_swap_estimator:
                swap_service_estimate = self.solve_swap_max_service_estimator(
                    design, label=f"swap_service_{iteration}"
                )
                scaled = self._service_result_as_profit_cut(
                    swap_service_estimate
                )
                if (
                    scaled.obj_value is not None
                    and scaled.cut_expr_data is not None
                ):
                    self._add_benders_cut(scaled, "swap_max_service")
                    self.flow_cut_stats.swap_max_service_cuts += 1

            core_reference = self._pareto_reference_design(design)
            if self.use_topology_estimator:
                topology_core_estimate = self.solve_topology_profit_estimator(
                    core_reference, label=f"topology_core_{iteration}"
                )
                if (
                    topology_core_estimate.obj_value is not None
                    and topology_core_estimate.cut_expr_data is not None
                ):
                    self._add_benders_cut(
                        topology_core_estimate, "topology_core_estimator"
                    )
                    self.flow_cut_stats.topology_estimator_cuts += 1
            if self.use_swap_estimator:
                swap_core_estimate = self.solve_swap_profit_estimator(
                    core_reference, label=f"swap_core_{iteration}"
                )
                if (
                    swap_core_estimate.obj_value is not None
                    and swap_core_estimate.cut_expr_data is not None
                ):
                    self._add_benders_cut(
                        swap_core_estimate, "swap_core_estimator"
                    )
                    self.flow_cut_stats.swap_estimator_cuts += 1
            self._initialize_or_update_core(design)
            lower_bound, pool_exact_cuts = self._evaluate_master_pool(
                iteration=iteration,
                lower_bound=lower_bound,
                deadline=t0 + time_limit,
            )
            upper_bound = max(upper_bound, lower_bound)

            tight_estimate = min(estimator_bounds) if estimator_bounds else math.inf
            screened = (
                math.isfinite(tight_estimate)
                and eta_value
                > tight_estimate + self.estimator_screen_tolerance
            )
            if screened:
                consecutive_screens += 1
            else:
                consecutive_screens = 0
            skip_exact = (
                screened
                and consecutive_screens
                <= self.max_consecutive_estimator_screens
            )
            if skip_exact:
                self.flow_cut_stats.screened_iterations += 1
                abs_gap = upper_bound - lower_bound
                rel_gap = abs_gap / max(1.0, abs(lower_bound))
                self.history.append(
                    {
                        "iter": iteration,
                        "UB": upper_bound,
                        "LB": lower_bound,
                        "abs_gap": abs_gap,
                        "rel_gap": rel_gap,
                        "eta": eta_value,
                        "topology_estimate": (
                            None
                            if topology_estimate is None
                            else topology_estimate.obj_value
                        ),
                        "swap_estimate": (
                            None
                            if swap_estimate is None
                            else swap_estimate.obj_value
                        ),
                        "topology_core_estimate": (
                            None
                            if topology_core_estimate is None
                            else topology_core_estimate.obj_value
                        ),
                        "swap_core_estimate": (
                            None
                            if swap_core_estimate is None
                            else swap_core_estimate.obj_value
                        ),
                        "topology_max_service": (
                            None
                            if topology_service_estimate is None
                            else topology_service_estimate.obj_value
                        ),
                        "swap_max_service": (
                            None
                            if swap_service_estimate is None
                            else swap_service_estimate.obj_value
                        ),
                        "network_net_estimate": (
                            None
                            if network_net_estimate is None
                            else network_net_estimate.obj_value
                        ),
                        "topology_cuts": topology_cuts,
                        "swap_cuts": swap_cuts,
                        "pool_exact_cuts": pool_exact_cuts,
                        "screened": 1,
                        "cuts": self.cut_count,
                        "initial_cuts": initial_cuts if iteration == 1 else 0,
                        "time": time.perf_counter() - t0,
                    }
                )
                if self.verbose:
                    print(
                        f"StrictIter {iteration:03d}: estimator screening "
                        f"eta={eta_value:.4f}, estimate={tight_estimate:.4f}, "
                        f"cuts={self.cut_count}"
                    )
                continue

            if screened:
                consecutive_screens = 0

            exact = self.solve_subproblem(
                design, label=f"strict_exact_{iteration}"
            )
            if exact.obj_value is None:
                if exact.status in {GRB.INFEASIBLE, GRB.INF_OR_UNBD}:
                    self._add_no_good_cut(design)
                    continue
                abs_gap = upper_bound - lower_bound
                rel_gap = abs_gap / max(1.0, abs(lower_bound))
                self.history.append(
                    {
                        "iter": iteration,
                        "UB": upper_bound,
                        "LB": lower_bound,
                        "abs_gap": abs_gap,
                        "rel_gap": rel_gap,
                        "eta": eta_value,
                        "topology_estimate": (
                            None
                            if topology_estimate is None
                            else topology_estimate.obj_value
                        ),
                        "swap_estimate": (
                            None
                            if swap_estimate is None
                            else swap_estimate.obj_value
                        ),
                        "topology_cuts": topology_cuts,
                        "swap_cuts": swap_cuts,
                        "pool_exact_cuts": pool_exact_cuts,
                        "screened": 0,
                        "exact_status": int(exact.status),
                        "exact_cut_added": 0,
                        "cuts": self.cut_count,
                        "initial_cuts": (
                            initial_cuts if iteration == 1 else 0
                        ),
                        "time": time.perf_counter() - t0,
                    }
                )
                continue

            total_obj = float(exact.obj_value) - fixed_cost
            if total_obj > lower_bound + 1e-7:
                lower_bound = total_obj
                self.best_total_obj = total_obj
                self.best_operational_obj = float(exact.obj_value)
                self.best_design = design
            upper_bound = max(upper_bound, lower_bound)

            exact_cut_added = (
                exact.cut_expr_data is not None
                and exact.rhs_at_reference is not None
            )
            if exact_cut_added:
                self._add_benders_cut(exact, "exact_conic_benders")

            abs_gap = upper_bound - lower_bound
            rel_gap = abs_gap / max(1.0, abs(lower_bound))
            self.history.append(
                {
                    "iter": iteration,
                    "UB": upper_bound,
                    "LB": lower_bound,
                    "abs_gap": abs_gap,
                    "rel_gap": rel_gap,
                    "eta": eta_value,
                    "sub_obj": exact.obj_value,
                    "exact_cut_added": int(exact_cut_added),
                    "fixed_cost": fixed_cost,
                    "topology_estimate": (
                        None
                        if topology_estimate is None
                        else topology_estimate.obj_value
                    ),
                    "swap_estimate": (
                        None
                        if swap_estimate is None
                        else swap_estimate.obj_value
                    ),
                    "topology_core_estimate": (
                        None
                        if topology_core_estimate is None
                        else topology_core_estimate.obj_value
                    ),
                    "swap_core_estimate": (
                        None
                        if swap_core_estimate is None
                        else swap_core_estimate.obj_value
                    ),
                    "topology_max_service": (
                        None
                        if topology_service_estimate is None
                        else topology_service_estimate.obj_value
                    ),
                    "swap_max_service": (
                        None
                        if swap_service_estimate is None
                        else swap_service_estimate.obj_value
                    ),
                    "network_net_estimate": (
                        None
                        if network_net_estimate is None
                        else network_net_estimate.obj_value
                    ),
                    "topology_cuts": topology_cuts,
                    "swap_cuts": swap_cuts,
                    "pool_exact_cuts": pool_exact_cuts,
                    "screened": 0,
                    "cuts": self.cut_count,
                    "initial_cuts": initial_cuts if iteration == 1 else 0,
                    "time": time.perf_counter() - t0,
                }
            )
            if self.verbose:
                print(
                    f"StrictIter {iteration:03d}: UB={upper_bound:.4f}, "
                    f"LB={lower_bound:.4f}, gap={rel_gap:.4%}, "
                    f"eta={eta_value:.4f}, exact={exact.obj_value:.4f}, "
                    f"cuts={self.cut_count}"
                )
            if (
                exact_cut_added
                and abs_gap <= tolerance * max(1.0, abs(lower_bound))
            ):
                break

        return self.best_design is not None
